148	  struct esp_hosted_ctrl_msg_s *msg;
149	
150	  msg = (struct esp_hosted_ctrl_msg_s *)buf;
151	  msg->cmd    = cmd;
152	  msg->status = 0;
153	  msg->len    = len;
154	
155	  if (len > 0 && data != NULL)
156	    {
157	      memcpy(buf + ESP_HOSTED_CTRL_MSG_HDR_LEN, data, len);
158	    }
159	
160	  return esp32p4_sdio_host_send(ESP_HOSTED_CHANNEL_CTRL,
161	                                buf, ESP_HOSTED_CTRL_MSG_HDR_LEN + len);
162	}
163	
164	static int esp_wifi_recv_ctrl(uint8_t *resp, uint16_t max_len)
165	{
166	  uint8_t channel;
167	  int ret;
168	
169	  ret = esp32p4_sdio_host_recv(&channel, resp, max_len);
170	  if (ret > 0 && channel == ESP_HOSTED_CHANNEL_CTRL)
171	    {
172	      return ret;
173	    }
174	
175	  return 0;
176	}
