178	/****************************************************************************
179	 * Private Functions - WiFi Operations
180	 ****************************************************************************/
181	
182	static int esp_wifi_do_connect(const char *ssid, const char *password)
183	{
184	  uint8_t payload[128];
185	  int ssid_len;
186	  int pwd_len;
187	  int ret;
188	
189	  ssid_len = strlen(ssid);
190	  pwd_len  = strlen(password);
191	
192	  if (ssid_len > MAX_SSID_LEN || pwd_len > 63)
193	    {
194	      return -EINVAL;
195	    }
196	
197	  /* Build connect payload: ssid_len(1) + ssid + pwd_len(1) + password */
198	
199	  payload[0] = (uint8_t)ssid_len;
200	  memcpy(payload + 1, ssid, ssid_len);
201	  payload[1 + ssid_len] = (uint8_t)pwd_len;
202	  memcpy(payload + 2 + ssid_len, password, pwd_len);
203	
204	  ret = esp_wifi_send_ctrl(ESP_HOSTED_CMD_CONNECT,
205	                           payload, 2 + ssid_len + pwd_len);
206	  if (ret < 0)
207	    {
208	      WIFI_ERR("Failed to send connect command: %d\n", ret);
209	      return ret;
210	    }
211	
212	  /* Wait for response */
213	
214	  int timeout = 100;
215	  while (timeout-- > 0)
216	    {
217	      ret = esp_wifi_recv_ctrl(g_wifi.ctrlbuf, sizeof(g_wifi.ctrlbuf));
218	      if (ret > 0)
219	        {
220	          struct esp_hosted_ctrl_msg_s *msg =
221	            (struct esp_hosted_ctrl_msg_s *)g_wifi.ctrlbuf;
222	
223	          if (msg->cmd == ESP_HOSTED_CMD_CONNECT)
224	            {
225	              if (msg->status == ESP_HOSTED_RESP_OK)
226	                {
227	                  WIFI_INFO("Connected to '%s'\n", ssid);
228	                  g_wifi.connected = true;
229	                  g_wifi.status = WIFI_STATUS_CONNECTED;
230	                  strncpy(g_wifi.ssid, ssid, MAX_SSID_LEN);
231	                  netdev_carrier_on(&g_wifi.netdev);
232	                  return OK;
233	                }
234	              else
235	                {
236	                  WIFI_ERR("Connect failed, status=%d\n", msg->status);
237	                  return -ECONNREFUSED;
238	                }
239	            }
240	        }
241	
242	      up_mdelay(100);
243	    }
244	
245	  WIFI_ERR("Connect timeout\n");
246	  return -ETIMEDOUT;
247	}
248	
249	static int esp_wifi_do_disconnect(void)
250	{
251	  int ret;
252	  uint8_t channel;
253	
254	  ret = esp_wifi_send_ctrl(ESP_HOSTED_CMD_DISCONNECT, NULL, 0);
255	  if (ret < 0)
256	    {
257	      return ret;
258	    }
259	
260	  /* Wait for response */
261	
262	  int timeout = 50;
263	  while (timeout-- > 0)
264	    {
265	      ret = esp32p4_sdio_host_recv(&channel, g_wifi.ctrlbuf,
266	                                   sizeof(g_wifi.ctrlbuf));
267	      if (ret > 0 && channel == ESP_HOSTED_CHANNEL_CTRL)
268	        {
269	          struct esp_hosted_ctrl_msg_s *msg =
270	            (struct esp_hosted_ctrl_msg_s *)g_wifi.ctrlbuf;
271	
272	          if (msg->cmd == ESP_HOSTED_CMD_DISCONNECT &&
273	              msg->status == ESP_HOSTED_RESP_OK)
274	            {
275	              WIFI_INFO("Disconnected\n");
276	              g_wifi.connected = false;
277	              g_wifi.status = WIFI_STATUS_DISCONNECTED;
278	              memset(g_wifi.ssid, 0, sizeof(g_wifi.ssid));
279	              netdev_carrier_off(&g_wifi.netdev);
280	              return OK;
281	            }
282	        }
283	
284	      up_mdelay(50);
285	    }
286	
287	  /* Assume disconnected anyway */
288	
289	  g_wifi.connected = false;
290	  g_wifi.status = WIFI_STATUS_DISCONNECTED;
291	  netdev_carrier_off(&g_wifi.netdev);
292	  return OK;
293	}
294	
295	static int esp_wifi_do_scan(void)
296	{
297	  int ret;
298	  int timeout;
299	
300	  WIFI_INFO("Starting WiFi scan\n");
301	
302	  ret = esp_wifi_send_ctrl(ESP_HOSTED_CMD_SCAN, NULL, 0);
303	  if (ret < 0)
304	    {
305	      WIFI_ERR("Failed to send scan command: %d\n", ret);
306	      return ret;
307	    }
308	
309	  g_wifi.scan_count = 0;
310	
311	  /* Collect scan results */
312	
313	  timeout = 200;
314	  while (timeout-- > 0)
315	    {
316	      uint8_t channel;
317	      ret = esp32p4_sdio_host_recv(&channel, g_wifi.ctrlbuf,
318	                                   sizeof(g_wifi.ctrlbuf));
319	      if (ret > 0 && channel == ESP_HOSTED_CHANNEL_CTRL)
320	        {
321	          struct esp_hosted_ctrl_msg_s *msg =
322	            (struct esp_hosted_ctrl_msg_s *)g_wifi.ctrlbuf;
323	
324	          if (msg->cmd == ESP_HOSTED_CMD_SCAN)
325	            {
326	              if (msg->status == ESP_HOSTED_RESP_OK && msg->len == 0)
327	                {
328	                  /* Scan complete */
329	
330	                  WIFI_INFO("Scan complete, %d results\n",
331	                            g_wifi.scan_count);
332	                  return OK;
333	                }
334	              else if (msg->status == ESP_HOSTED_RESP_SCAN_RESULT &&
335	                       msg->len > 0)
336	                {
337	                  /* Parse scan result */
338	
339	                  if (g_wifi.scan_count < MAX_SCAN_RESULTS &&
340	                      msg->len >= sizeof(struct esp_hosted_scan_result_s))
341	                    {
342	                      memcpy(&g_wifi.scan_results[g_wifi.scan_count],
343	                             g_wifi.ctrlbuf + ESP_HOSTED_CTRL_MSG_HDR_LEN,
344	                             sizeof(struct esp_hosted_scan_result_s));
345	                      g_wifi.scan_count++;
346	                    }
347	                }
348	            }
349	        }
350	
351	      up_mdelay(50);
352	    }
353	
354	  WIFI_ERR("Scan timeout\n");
355	  return -ETIMEDOUT;
356	}
