361	
362	static int esp_wifi_ifup(FAR struct net_driver_s *dev)
363	{
364	  FAR struct esp_wifi_dev_s *priv =
365	    (FAR struct esp_wifi_dev_s *)dev->d_private;
366	
367	  WIFI_INFO("Bringing up WiFi interface\n");
368	
369	  priv->ifup = true;
370	
371	  /* Start periodic poll work */
372	
373	  work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
374	             priv, WIFI_POLL_INTERVAL);
375	
376	  return OK;
377	}
378	
379	static int esp_wifi_ifdown(FAR struct net_driver_s *dev)
380	{
381	  FAR struct esp_wifi_dev_s *priv =
382	    (FAR struct esp_wifi_dev_s *)dev->d_private;
383	
384	  WIFI_INFO("Bringing down WiFi interface\n");
385	
386	  work_cancel(LPWORK, &priv->pollwork);
387	
388	  if (priv->connected)
389	    {
390	      esp_wifi_do_disconnect();
391	    }
392	
393	  priv->ifup = false;
394	  return OK;
395	}
396	
397	static int esp_wifi_transmit(FAR struct net_driver_s *dev)
398	{
399	  int ret;
400	
401	  WIFI_DBG("TX %d bytes\n", dev->d_len);
402	
403	  ret = esp32p4_sdio_host_send(ESP_HOSTED_CHANNEL_DATA,
404	                               dev->d_buf, dev->d_len);
405	  if (ret < 0)
406	    {
407	      WIFI_ERR("TX failed: %d\n", ret);
408	    }
409	
410	  return ret;
411	}
412	
413	static int esp_wifi_txavail(FAR struct net_driver_s *dev)
414	{
415	  if (dev->d_buf != NULL)
416	    {
417	      return esp_wifi_transmit(dev);
418	    }
419	
420	  return OK;
421	}
