500	/****************************************************************************
501	 * Private Functions - Polling / Receive
502	 ****************************************************************************/
503	
504	static void esp_wifi_poll_work(FAR void *arg)
505	{
506	  FAR struct esp_wifi_dev_s *priv = (FAR struct esp_wifi_dev_s *)arg;
507	  int ret;
508	  uint8_t channel;
509	
510	  if (!priv->ifup)
511	    {
512	      return;
513	    }
514	
515	  /* Try to receive data from SDIO */
516	
517	  ret = esp32p4_sdio_host_recv(&channel, priv->rxbuf,
518	                               sizeof(priv->rxbuf));
519	  if (ret > 0)
520	    {
521	      if (channel == ESP_HOSTED_CHANNEL_DATA)
522	        {
523	          /* Pass received packet to the network stack */
524	
525	          priv->netdev.d_buf = priv->rxbuf;
526	          priv->netdev.d_len = ret;
527	
528	          ipv4_input(&priv->netdev);
529	
530	          /* Reset buffer pointer */
531	
532	          priv->netdev.d_buf = NULL;
533	          priv->netdev.d_len = 0;
534	        }
535	      else if (channel == ESP_HOSTED_CHANNEL_CTRL)
536	        {
537	          /* Handle control response */
538	
539	          WIFI_DBG("Control response (%d bytes)\n", ret);
540	        }
541	    }
542	
543	  /* Re-schedule poll work */
544	
545	  if (priv->ifup)
546	    {
547	      work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
548	                 priv, WIFI_POLL_INTERVAL);
549	    }
550	}
