552	/****************************************************************************
553	 * Name: esp_wifi_init_protocol
554	 *
555	 * Description:
556	 *   Initialize the esp_hosted protocol - handshake with ESP32-C6
557	 *   and get MAC address.
558	 *
559	 ****************************************************************************/
560	
561	static int esp_wifi_init_protocol(void)
562	{
563	  int ret;
564	  int timeout;
565	  uint8_t channel;
566	
567	  WIFI_INFO("Initializing esp_hosted protocol\n");
568	
569	  /* Send init command to ESP32-C6 */
570	
571	  ret = esp_wifi_send_ctrl(ESP_HOSTED_CMD_INIT, NULL, 0);
572	  if (ret < 0)
573	    {
574	      WIFI_ERR("Failed to send init command: %d\n", ret);
575	      return ret;
576	    }
577	
578	  /* Wait for init response */
579	
580	  timeout = 100;
581	  while (timeout-- > 0)
582	    {
583	      ret = esp32p4_sdio_host_recv(&channel, g_wifi.ctrlbuf,
584	                                   sizeof(g_wifi.ctrlbuf));
585	      if (ret > 0 && channel == ESP_HOSTED_CHANNEL_CTRL)
586	        {
587	          struct esp_hosted_ctrl_msg_s *msg =
588	            (struct esp_hosted_ctrl_msg_s *)g_wifi.ctrlbuf;
589	
590	          if (msg->cmd == ESP_HOSTED_CMD_INIT &&
591	              msg->status == ESP_HOSTED_RESP_OK)
592	            {
593	              /* Extract MAC address from response if available */
594	
595	              if (msg->len >= 6)
596	                {
597	                  memcpy(g_wifi.mac,
598	                         g_wifi.ctrlbuf + ESP_HOSTED_CTRL_MSG_HDR_LEN, 6);
599	                  WIFI_INFO("MAC: %02x:%02x:%02x:%02x:%02x:%02x\n",
600	                            g_wifi.mac[0], g_wifi.mac[1], g_wifi.mac[2],
601	                            g_wifi.mac[3], g_wifi.mac[4], g_wifi.mac[5]);
602	                }
603	
604	              WIFI_INFO("esp_hosted protocol initialized\n");
605	              return OK;
606	            }
607	        }
608	
609	      up_mdelay(50);
610	    }
611	
612	  /* If no response, use default MAC and continue */
613	
614	  WIFI_INFO("No init response, using default MAC\n");
615	  g_wifi.mac[0] = 0x02;
616	  g_wifi.mac[1] = 0x00;
617	  g_wifi.mac[2] = 0x00;
618	  g_wifi.mac[3] = 0x00;
619	  g_wifi.mac[4] = 0x00;
620	  g_wifi.mac[5] = 0x01;
621	
622	  return OK;
623	}
624	
625	/****************************************************************************
626	 * Public Functions
627	 ****************************************************************************/
628	
629	/****************************************************************************
630	 * Name: esp32p4_wifi_init
631	 ****************************************************************************/
632	
633	int esp32p4_wifi_init(void)
634	{
635	  int ret;
636	
637	  up_puts("WIFI: init entry\n");
638	
639	  memset(&g_wifi, 0, sizeof(g_wifi));
640	  nxmutex_init(&g_wifi.lock);
641	
642	  /* Step 1: Initialize SDIO host */
643	
644	  ret = esp32p4_sdio_host_init();
645	  if (ret < 0)
646	    {
647	      WIFI_ERR("SDIO host init failed: %d\n", ret);
648	      up_puts("WIFI: SDIO failed, registering dummy device\n");
649	      /* Use default MAC when SDIO fails */
650	      g_wifi.mac[0] = 0x02;
651	      g_wifi.mac[1] = 0x00;
652	      g_wifi.mac[2] = 0x00;
653	      g_wifi.mac[3] = 0x00;
654	      g_wifi.mac[4] = 0x00;
655	      g_wifi.mac[5] = 0x01;
656	    }
657	  else
658	    {
659	      /* Step 2: Initialize esp_hosted protocol (only if SDIO works) */
660	
661	      ret = esp_wifi_init_protocol();
662	      if (ret < 0)
663	        {
664	          WIFI_ERR("Protocol init failed: %d\n", ret);
665	          /* Continue anyway, use default MAC */
666	        }
667	    }
668	
669	  /* Step 3: Register network device */
670	
671	  g_wifi.netdev.d_ifup    = esp_wifi_ifup;
672	  g_wifi.netdev.d_ifdown  = esp_wifi_ifdown;
673	  g_wifi.netdev.d_txavail = esp_wifi_txavail;
674	#ifdef CONFIG_NETDEV_IOCTL
675	  g_wifi.netdev.d_ioctl   = esp_wifi_ioctl;
676	#endif
677	  g_wifi.netdev.d_private = &g_wifi;
678	
679	  memcpy(g_wifi.netdev.d_mac.ether.ether_addr_octet, g_wifi.mac, 6);
680	
681	  up_puts("WIFI: registering netdev...\n");
682	  ret = netdev_register(&g_wifi.netdev, NET_LL_IEEE80211);
683	  if (ret < 0)
684	    {
685	      up_puts("WIFI: netdev_register FAILED\n");
686	      return ret;
687	    }
688	
689	  up_puts("WIFI: netdev registered OK\n");
690	  return OK;
691	}
