27	/****************************************************************************
28	 * Pre-processor Definitions
29	 ****************************************************************************/
30	
31	#define SDIO_TAG "sdio"
32	#define SDIO_ERR(...)   syslog(LOG_ERR, SDIO_TAG ": " __VA_ARGS__)
33	#define SDIO_INFO(...)  syslog(LOG_INFO, SDIO_TAG ": " __VA_ARGS__)
34	#define SDIO_DBG(...)   syslog(LOG_DEBUG, SDIO_TAG ": " __VA_ARGS__)
35	
36	/* SDIO command definitions */
37	
38	#define SDIO_CMD_GO_IDLE_STATE      0   /* CMD0  */
39	#define SDIO_CMD_SEND_OP_COND       5   /* CMD5  */
40	#define SDIO_CMD_SEND_RELATIVE_ADDR 3   /* CMD3  */
41	#define SDIO_CMD_SELECT_CARD        7   /* CMD7  */
42	#define SDIO_CMD_IO_RW_DIRECT      52   /* CMD52 */
43	#define SDIO_CMD_IO_RW_EXTENDED    53   /* CMD53 */
44	
45	/* SDIO response types */
46	
47	#define SDIO_RESP_NONE  0
48	#define SDIO_RESP_R4    1
49	#define SDIO_RESP_R6    2
50	
51	/* CMD52 argument fields */
52	
53	#define CMD52_FUNC(x)       (((x) & 0x7) << 28)
54	#define CMD52_BLOCK_MODE    (1 << 27)
55	#define CMD52_OP_WRITE      (1 << 31)
56	#define CMD52_RAW           (1 << 27)
57	#define CMD52_REG_ADDR(x)   (((x) & 0x1FFFF) << 9)
58	
59	/* CMD53 argument fields */
60	
61	#define CMD53_FUNC(x)       (((x) & 0x7) << 28)
62	#define CMD53_BLOCK_MODE    (1 << 27)
63	#define CMD53_OP_WRITE      (1 << 31)
64	#define CMD53_REG_ADDR(x)   (((x) & 0x1FFFF) << 9)
65	#define CMD53_COUNT(x)      (((x) & 0x1FF))
66	
67	/* SDIO register addresses */
68	
69	#define SDIO_CCCR_IO_READY   0x02
70	#define SDIO_CCCR_IO_ENABLE  0x02
71	#define SDIO_CCCR_IO_ABORT   0x06
72	#define SDIO_CCCR_BUS_CTRL   0x07
73	#define SDIO_CCCR_CAPABILITY 0x08
74	
75	/* esp_hosted SDIO register base for function 1 */
76	
77	#define ESP_HOSTED_IO_PORT   0x00000
78	
79	/* Timing */
80	
81	#define SDIO_INIT_TIMEOUT_MS   1000
82	#define SDIO_CMD_TIMEOUT_MS    100
83	#define SDIO_DATA_TIMEOUT_MS   500
84	
85	/****************************************************************************
86	 * Private Types
87	 ****************************************************************************/
88	
89	struct esp_sdio_host_dev_s
90	{
91	  mutex_t             lock;          /* Mutex for thread safety */
92	  uint8_t             bus_num;       /* SDIO bus number */
93	  uint32_t           freq;          /* Clock frequency in Hz */
94	  uint8_t             gpio_data_rdy; /* DATA_READY GPIO from C6 */
95	  bool               initialized;   /* Initialization state */
96	  uint16_t           rca;           /* Relative Card Address */
97	  uint8_t             buffer[2048];  /* Transfer buffer */
98	};
99	
100	/****************************************************************************
101	 * Private Data
102	 ****************************************************************************/
103	
104	static struct esp_sdio_host_dev_s g_sdio;
105	
106	/****************************************************************************
107	 * Private Functions - Low Level SDIO
108	 ****************************************************************************/
109	
110	/****************************************************************************
111	 * Name: sdio_send_cmd
112	 *
113	 * Description:
114	 *   Send an SDIO command and optionally read the response.
115	 *   Uses direct register access to the ESP32-P4 SDMMC peripheral.
116	 *
117	 ****************************************************************************/
118	
119	/* ESP32-P4 SDMMC register base address (from sdmmc_struct.h) */
120	
121	#define SDMMC_BASE          0x50083000
122	#define SDMMC_CTRL          (SDMMC_BASE + 0x00)  /* Control register */
123	#define SDMMC_CLKDIV        (SDMMC_BASE + 0x08)  /* Clock divider */
124	#define SDMMC_CLKSRC        (SDMMC_BASE + 0x0C)  /* Clock source */
125	#define SDMMC_CLKENA        (SDMMC_BASE + 0x10)  /* Clock enable */
126	#define SDMMC_TMOUT         (SDMMC_BASE + 0x14)  /* Timeout */
127	#define SDMMC_CTYPE         (SDMMC_BASE + 0x18)  /* Card type (bus width) */
128	#define SDMMC_BLKSIZ        (SDMMC_BASE + 0x1C)  /* Block size */
129	#define SDMMC_BYTCNT        (SDMMC_BASE + 0x20)  /* Byte count */
130	#define SDMMC_INTMASK       (SDMMC_BASE + 0x24)  /* Interrupt mask */
131	#define SDMMC_CMDARG        (SDMMC_BASE + 0x28)  /* Command argument */
132	#define SDMMC_CMD           (SDMMC_BASE + 0x2C)  /* Command register */
133	#define SDMMC_RESP0         (SDMMC_BASE + 0x30)  /* Response 0 */
134	#define SDMMC_RESP1         (SDMMC_BASE + 0x34)  /* Response 1 */
135	#define SDMMC_RESP2         (SDMMC_BASE + 0x38)  /* Response 2 */
136	#define SDMMC_RESP3         (SDMMC_BASE + 0x3C)  /* Response 3 */
137	#define SDMMC_MINTSTS       (SDMMC_BASE + 0x40)  /* Masked interrupt status */
138	#define SDMMC_RINTSTS       (SDMMC_BASE + 0x44)  /* Raw interrupt status */
139	#define SDMMC_STATUS        (SDMMC_BASE + 0x48)  /* Status register */
140	#define SDMMC_FIFOTH        (SDMMC_BASE + 0x4C)  /* FIFO threshold */
141	#define SDMMC_CDETECT       (SDMMC_BASE + 0x50)  /* Card detect */
142	#define SDMMC_WRTPRT        (SDMMC_BASE + 0x54)  /* Write protect */
143	#define SDMMC_UHS           (SDMMC_BASE + 0x74)  /* UHS register */
144	#define SDMMC_RST_N         (SDMMC_BASE + 0x78)  /* Hardware reset */
145	#define SDMMC_BMOD          (SDMMC_BASE + 0x80)  /* Bus mode */
146	#define SDMMC_DBADDR        (SDMMC_BASE + 0x88)  /* Descriptor base addr */
147	#define SDMMC_IDSTS         (SDMMC_BASE + 0x8C)  /* DMA status */
148	#define SDMMC_IDINTEN       (SDMMC_BASE + 0x90)  /* DMA interrupt enable */
149	#define SDMMC_DSCADDR       (SDMMC_BASE + 0x94)  /* Descriptor address */
150	#define SDMMC_BUFADDR       (SDMMC_BASE + 0x98)  /* Buffer address */
151	#define SDMMC_FIFO          (SDMMC_BASE + 0x200)  /* Data FIFO */
152	#define SDMMC_CLK_EDGE_SEL  (SDMMC_BASE + 0x7FC)  /* Clock edge select */
153	
154	static int sdio_send_cmd(uint32_t cmd, uint32_t arg,
155	                         uint32_t *resp, int resp_type)
156	{
157	  volatile uint32_t *cmd_reg  = (volatile uint32_t *)SDMMC_CMD;
158	  volatile uint32_t *arg_reg  = (volatile uint32_t *)SDMMC_CMDARG;
159	  volatile uint32_t *rint_reg = (volatile uint32_t *)SDMMC_RINTSTS;
160	  volatile uint32_t *status   = (volatile uint32_t *)SDMMC_STATUS;
161	  int timeout;
162	
163	  /* Wait for controller not busy (data state machine idle) */
164	
165	  timeout = SDIO_CMD_TIMEOUT_MS;
166	  while ((*status & (1 << 9)) && timeout-- > 0)  /* bit 9: data busy */
167	    {
168	      up_mdelay(1);
169	    }
170	
171	  /* Clear pending interrupts */
172	
173	  *rint_reg = 0xFFFFFFFF;
174	
175	  /* Set argument */
176	
177	  *arg_reg = arg;
178	
179	  /* Build command register value
180	   * Bits [5:0]   = command index
181	   * Bit  [6]     = response expected
182	   * Bit  [7]     = check response CRC
183	   * Bit  [8]     = data expected (for CMD53)
184	   * Bit  [9]     = read/write (1=write)
185	   * Bit  [10]    = send initialization sequence
186	   * Bit  [13]    = wait for data complete
187	   * Bit  [21]    = stop abort command
188	   * Bit  [31]    = start command (CI)
189	   */
190	
191	  uint32_t cmd_val = (cmd & 0x3F) | (1 << 31);  /* cmd index + start */
192	
193	  /* Set response type */
194	
195	  switch (resp_type)
196	    {
197	      case SDIO_RESP_R4:
198	        cmd_val |= (1 << 6);   /* Response expected */
199	        break;
200	      case SDIO_RESP_R6:
201	        cmd_val |= (1 << 6);   /* Response expected */
202	        cmd_val |= (1 << 7);   /* Check response CRC */
203	        break;
204	      default:
205	        break;
206	    }
207	
208	  /* For CMD0, send initialization sequence */
209	
210	  if (cmd == 0)
211	    {
212	      cmd_val |= (1 << 10);
213	    }
214	
215	  *cmd_reg = cmd_val;
216	
217	  /* Wait for command done (CI bit clears, or command done interrupt) */
218	
219	  timeout = SDIO_CMD_TIMEOUT_MS;
220	  while ((*cmd_reg & (1 << 31)) && timeout-- > 0)
221	    {
222	      up_mdelay(1);
223	    }
224	
225	  if (timeout <= 0)
226	    {
227	      up_puts("SDIO: CMD timeout\n");
228	      return -ETIMEDOUT;
229	    }
230	
231	  /* Check raw interrupt status for errors */
232	
233	  uint32_t rint = *rint_reg;
234	
235	  if (rint & (1 << 1))  /* Response error */
236	    {
237	      up_puts("SDIO: CMD resp error\n");
238	      *rint_reg = (1 << 1);
239	      return -EIO;
240	    }
241	
242	  if (rint & (1 << 8))  /* Response timeout */
243	    {
244	      up_puts("SDIO: CMD resp timeout\n");
245	      *rint_reg = (1 << 8);
246	      return -ETIMEDOUT;
247	    }
248	
249	  if (rint & (1 << 2))  /* Command done */
250	    {
251	      *rint_reg = (1 << 2);  /* Clear interrupt */
252	    }
253	
254	  /* Read response if requested */
255	
256	  if (resp != NULL && resp_type != SDIO_RESP_NONE)
257	    {
258	      *resp = *((volatile uint32_t *)SDMMC_RESP0);
259	    }
260	
261	  return OK;
262	}
