265	 * Name: sdio_cmd52_read
266	 *
267	 * Description:
268	 *   CMD52 - IO Read Direct (single byte)
269	 *
270	 ****************************************************************************/
271	
272	static int sdio_cmd52_read(uint8_t func, uint32_t addr, uint8_t *data)
273	{
274	  uint32_t arg;
275	  uint32_t resp;
276	  int ret;
277	
278	  arg = CMD52_FUNC(func) | CMD52_REG_ADDR(addr);
279	
280	  ret = sdio_send_cmd(SDIO_CMD_IO_RW_DIRECT, arg, &resp, SDIO_RESP_R4);
281	  if (ret < 0)
282	    {
283	      return ret;
284	    }
285	
286	  if (data != NULL)
287	    {
288	      *data = (resp >> 8) & 0xFF;
289	    }
290	
291	  return OK;
292	}
