325	/****************************************************************************
326	 * Name: sdio_cmd53_read
327	 *
328	 * Description:
329	 *   CMD53 - IO Read Extended (block transfer)
330	 *
331	 ****************************************************************************/
332	
333	static int sdio_cmd53_read(uint8_t func, uint32_t addr,
334	                           uint8_t *buf, uint16_t count)
335	{
336	  uint32_t arg;
337	  uint32_t resp;
338	  int ret;
339	  int i;
340	  int timeout;
341	
342	  /* Configure block size and byte count */
343	
344	  volatile uint32_t *blksiz = (volatile uint32_t *)SDMMC_BLKSIZ;
345	  volatile uint32_t *bytcnt = (volatile uint32_t *)SDMMC_BYTCNT;
346	  *blksiz = count;
347	  *bytcnt = count;
348	
349	  /* Build CMD53 argument: read, byte mode */
350	
351	  arg = CMD53_FUNC(func) | CMD53_REG_ADDR(addr) | CMD53_COUNT(count);
352	
353	  ret = sdio_send_cmd(SDIO_CMD_IO_RW_EXTENDED, arg, &resp, SDIO_RESP_R4);
354	  if (ret < 0)
355	    {
356	      return ret;
357	    }
358	
359	  /* Wait for data ready (FIFO not empty) */
360	
361	  volatile uint32_t *status = (volatile uint32_t *)SDMMC_STATUS;
362	  timeout = SDIO_DATA_TIMEOUT_MS;
363	  while ((*status & (1 << 4)) && timeout-- > 0)  /* bit 4: FIFO empty */
364	    {
365	      up_mdelay(1);
366	    }
367	
368	  /* Read data from FIFO */
369	
370	  volatile uint32_t *fifo = (volatile uint32_t *)SDMMC_FIFO;
371	
372	  for (i = 0; i < (count + 3) / 4; i++)
373	    {
374	      uint32_t word = *fifo;
375	      int j;
376	      for (j = 0; j < 4 && (i * 4 + j) < count; j++)
377	        {
378	          buf[i * 4 + j] = (word >> (j * 8)) & 0xFF;
379	        }
380	    }
381	
382	  return count;
383	}
384	
385	/****************************************************************************
386	 * Name: sdio_cmd53_write
387	 *
388	 * Description:
389	 *   CMD53 - IO Write Extended (block transfer)
390	 *
391	 ****************************************************************************/
392	
393	static int sdio_cmd53_write(uint8_t func, uint32_t addr,
394	                            const uint8_t *buf, uint16_t count)
395	{
396	  uint32_t arg;
397	  uint32_t resp;
398	  int ret;
399	  int i;
400	
401	  /* Configure block size and byte count */
402	
403	  volatile uint32_t *blksiz = (volatile uint32_t *)SDMMC_BLKSIZ;
404	  volatile uint32_t *bytcnt = (volatile uint32_t *)SDMMC_BYTCNT;
405	  *blksiz = count;
406	  *bytcnt = count;
407	
408	  /* Build CMD53 argument: write, byte mode */
409	
410	  arg = CMD53_OP_WRITE | CMD53_FUNC(func) |
411	        CMD53_REG_ADDR(addr) | CMD53_COUNT(count);
412	
413	  /* Write data to FIFO before sending command */
414	
415	  volatile uint32_t *fifo = (volatile uint32_t *)SDMMC_FIFO;
416	
417	  for (i = 0; i < (count + 3) / 4; i++)
418	    {
419	      uint32_t word = 0;
420	      int j;
421	      for (j = 0; j < 4 && (i * 4 + j) < count; j++)
422	        {
423	          word |= ((uint32_t)buf[i * 4 + j]) << (j * 8);
424	        }
425	      *fifo = word;
426	    }
427	
428	  ret = sdio_send_cmd(SDIO_CMD_IO_RW_EXTENDED, arg, &resp, SDIO_RESP_R4);
429	  if (ret < 0)
430	    {
431	      return ret;
432	    }
433	
434	  return count;
435	}
