703	/****************************************************************************
704	 * Name: esp32p4_sdio_host_init
705	 ****************************************************************************/
706	
707	int esp32p4_sdio_host_init(void)
708	{
709	  int ret;
710	
711	  memset(&g_sdio, 0, sizeof(g_sdio));
712	  nxmutex_init(&g_sdio.lock);
713	
714	  g_sdio.bus_num       = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_BUS;
715	  g_sdio.freq          = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_FREQ;
716	  g_sdio.gpio_data_rdy = CONFIG_ESP32P4_WIFI_HOSTED_GPIO_DATA_RDY;
717	
718	  /* Initialize SDIO hardware */
719	
720	  ret = sdio_init_hw();
721	  if (ret < 0)
722	    {
723	      SDIO_ERR("SDIO hardware init failed: %d\n", ret);
724	      return ret;
725	    }
726	
727	  g_sdio.initialized = true;
728	  return OK;
729	}
