731	/****************************************************************************
732	 * Name: esp32p4_sdio_host_send
733	 ****************************************************************************/
734	
735	int esp32p4_sdio_host_send(uint8_t channel, const uint8_t *data,
736	                           uint16_t len)
737	{
738	  struct esp_hosted_header_s hdr;
739	  uint8_t *pkt;
740	  int ret;
741	
742	  if (!g_sdio.initialized)
743	    {
744	      return -ENODEV;
745	    }
746	
747	  /* Build esp_hosted packet */
748	
749	  hdr.channel  = channel;
750	  hdr.reserved = 0;
751	  hdr.len      = len;
752	  hdr.offset   = sizeof(hdr);
753	  hdr.checksum = channel + len;
754	
755	  /* Copy header + data to buffer */
756	
757	  pkt = g_sdio.buffer;
758	  memcpy(pkt, &hdr, sizeof(hdr));
759	  memcpy(pkt + sizeof(hdr), data, len);
760	
761	  nxmutex_lock(&g_sdio.lock);
762	
763	  /* Write to SDIO function 1 */
764	
765	  ret = sdio_cmd53_write(1, ESP_HOSTED_IO_PORT,
766	                         pkt, sizeof(hdr) + len);
767	
768	  nxmutex_unlock(&g_sdio.lock);
769	
770	  if (ret < 0)
771	    {
772	      SDIO_ERR("SDIO send failed: %d\n", ret);
773	      return ret;
774	    }
775	
776	  return OK;
777	}
