779	/****************************************************************************
780	 * Name: esp32p4_sdio_host_recv
781	 ****************************************************************************/
782	
783	int esp32p4_sdio_host_recv(uint8_t *channel, uint8_t *data,
784	                           uint16_t max_len)
785	{
786	  struct esp_hosted_header_s hdr;
787	  int ret;
788	  int pkt_len;
789	
790	  if (!g_sdio.initialized)
791	    {
792	      return -ENODEV;
793	    }
794	
795	  nxmutex_lock(&g_sdio.lock);
796	
797	  /* Read header first (8 bytes) */
798	
799	  ret = sdio_cmd53_read(1, ESP_HOSTED_IO_PORT,
800	                        (uint8_t *)&hdr, sizeof(hdr));
801	  if (ret < (int)sizeof(hdr))
802	    {
803	      nxmutex_unlock(&g_sdio.lock);
804	      return 0;  /* No data available */
805	    }
806	
807	  /* Validate header */
808	
809	  if (hdr.len == 0 || hdr.len > max_len)
810	    {
811	      nxmutex_unlock(&g_sdio.lock);
812	      return 0;
813	    }
814	
815	  /* Read payload */
816	
817	  pkt_len = hdr.len;
818	  ret = sdio_cmd53_read(1, ESP_HOSTED_IO_PORT + sizeof(hdr),
819	                        data, pkt_len);
820	  nxmutex_unlock(&g_sdio.lock);
821	
822	  if (ret < pkt_len)
823	    {
824	      SDIO_ERR("SDIO recv payload failed: %d\n", ret);
825	      return 0;
826	    }
827	
828	  if (channel != NULL)
829	    {
830	      *channel = hdr.channel;
831	    }
832	
833	  return pkt_len;
834	}
