592	   * resets the DW-GDMA controller (both go through the shared high-level
593	   * driver), so the order here only determines channel assignment: the
594	   * camera claims channel 0 and the display gets channel 1.
595	   */
596	
597	  esp_mipi_dsi_start_refresh();
598	
599	  /* The demo thread repaints the whole framebuffer every 2 seconds, which
600	   * would stomp on camera frames. Only run it as a standalone display
601	   * self-test, i.e. when there is no camera preview to interfere with.
602	   */
603	
604	#ifndef CONFIG_ESP32P4_CAMERA
605	  esp_mipi_dsi_start_demo();
606	#endif
607	#endif
608	
609	
610	
611	  /* If we got here then perhaps not all initialization was successful, but
612	   * at least enough succeeded to bring-up NSH with perhaps reduced
613	   * capabilities.
614	   */
615	
616	  return ret;
