7	/*
8	 *  SDIO Driver
9	 *  ===========
10	 *
11	 *  TX Path (Host -> Slave):
12	 *  ------------------------
13	 *  1. `esp_hosted_tx()`: Higher-level modules call this function to send data.
14	 *  2. `to_slave_queue`: The data is placed into a priority queue.
15	 *  3. `sdio_write_task`: This thread waits for data on the queue, retrieves it,
16	 *     and writes it to the SDIO bus.
17	 *
18	 *  RX Path (Slave -> Host):
19	 *  ------------------------
20	 *  1. `sdio_read_task`: This thread waits for an interrupt from the slave,
21	 *     reads the raw data stream into a double buffer, and signals the next
22	 *     thread.
23	 *  2. `sdio_data_to_rx_buf_task`: Processes the stream from the double buffer,
24	 *     extracts individual packets, and places them onto the `from_slave_queue`.
25	 *  3. `sdio_process_rx_task`: Retrieves packets from the queue and dispatches
26	 *     them to the appropriate higher-level handler (e.g., WiFi, BT).
27	 *
28	 *
29	 *
30	 *        Host MCU
31	 *        +--------------------------------------------------------------------------------------------------+
32	 *        | TX Path (Host -> Slave)                                    RX Path (Slave -> Host)               |
33	 *        | +------------------------------------------------------+   +-----------------------------------+ |
34	 *        | | Higher Layers (e.g. Wi-Fi)                           |   | SDIO Bus                          | |
35	 *        | |      |                                               |   |    |                              | |
36	 *        | |      v                                               |   |    v                              | |
37	 *        | | esp_hosted_tx()                                      |   | sdio_read_task (Thread)           | |
38	 *        | |      |                                               |   |    |                              | |
39	 *        | |      v                                               |   |    | Data Stream                  | |
40	 *        | | to_slave_queue (Queue)                               |   |    v                              | |
41	 *        | |      |                                               |   | Double Buffer                     | |
42	 *        | |      v                                               |   |    |                              | |
43	 *        | | sdio_write_task (Thread)                             |   |    v                              | |
44	 *        | |      |                                               |   | sdio_data_to_rx_buf_task (Thread) | |
45	 *        | |      v                                               |   |    |                              | |
46	 *        | | SDIO Bus                                             |   |    | Packets                      | |
47	 *        | +------------------------------------------------------+   |    v                              | |
48	 *        |                                                            | from_slave_queue (Queue)          | |
49	 *        |                                                            |    |                              | |
50	 *        |                                                            |    v                              | |
51	 *        |                                                            | sdio_process_rx_task (Thread)     | |
52	 *        |                                                            |    |                              | |
53	 *        |                                                            |    v                              | |
54	 *        |                                                            | Higher Layers (Wi-Fi, BT, etc)    | |
55	 *        |                                                            +-----------------------------------+ |
56	 *        +--------------------------------------------------------------------------------------------------+
57	 *
58	 *
59	 */
