281	void bus_deinit_internal(void *bus_handle)
282	{
283		uint8_t prio_q_idx = 0;
284	
285		if (sdio_read_thread) {
286			g_h.funcs->_h_thread_cancel(sdio_read_thread);
287			sdio_read_thread = NULL;
288		}
289	
290		if (sdio_write_thread) {
291			g_h.funcs->_h_thread_cancel(sdio_write_thread);
292			sdio_write_thread = NULL;
293		}
294	
295		if (sdio_process_rx_thread) {
296			g_h.funcs->_h_thread_cancel(sdio_process_rx_thread);
297			sdio_process_rx_thread = NULL;
298		}
299	
300		if (sdio_rx_buf_thread) {
301			g_h.funcs->_h_thread_cancel(sdio_rx_buf_thread);
302			sdio_rx_buf_thread = NULL;
303		}
304	
305		for (prio_q_idx=0; prio_q_idx<MAX_PRIORITY_QUEUES;prio_q_idx++) {
306			if (to_slave_queue[prio_q_idx]) {
307				/* Drain to_slave_queue before destroying to prevent buffer leaks */
308				interface_buffer_handle_t buf_handle;
309				int count = 0;
310				while (g_h.funcs->_h_dequeue_item(to_slave_queue[prio_q_idx], &buf_handle, 0) == 0) {
311					/* Free buffer using the provided free function */
312					if (buf_handle.priv_buffer_handle && buf_handle.free_buf_handle) {
313						buf_handle.free_buf_handle(buf_handle.priv_buffer_handle);
314						count++;
315					}
316				}
317				ESP_LOGD(TAG, "Drained %d buffers from to_slave_queue[%d]", count, prio_q_idx);
318				g_h.funcs->_h_destroy_queue(to_slave_queue[prio_q_idx]);
319				to_slave_queue[prio_q_idx] = NULL;
320			}
321			if (from_slave_queue[prio_q_idx]) {
322				/* Drain from_slave_queue before destroying to prevent buffer leaks */
323				interface_buffer_handle_t buf_handle;
324				int count = 0;
325				while (g_h.funcs->_h_dequeue_item(from_slave_queue[prio_q_idx], &buf_handle, 0) == 0) {
326					/* Free buffer using the provided free function */
327					if (buf_handle.priv_buffer_handle && buf_handle.free_buf_handle) {
328						buf_handle.free_buf_handle(buf_handle.priv_buffer_handle);
329						count++;
330					}
331				}
332				ESP_LOGD(TAG, "Drained %d buffers from from_slave_queue[%d]", count, prio_q_idx);
333				g_h.funcs->_h_destroy_queue(from_slave_queue[prio_q_idx]);
334				from_slave_queue[prio_q_idx] = NULL;
335			}
336		}
337	
338		if (sem_to_slave_queue) {
339			g_h.funcs->_h_destroy_semaphore(sem_to_slave_queue);
340			sem_to_slave_queue = NULL;
341		}
342		if (sem_from_slave_queue) {
343			g_h.funcs->_h_destroy_semaphore(sem_from_slave_queue);
344			sem_from_slave_queue = NULL;
345		}
346		if (sem_double_buf_xfer_data) {
347			g_h.funcs->_h_destroy_semaphore(sem_double_buf_xfer_data);
348			sem_double_buf_xfer_data = NULL;
349		}
350	
351	#if DO_COMBINED_REG_READ
352	    if (reg_buf) {
353	        g_h.funcs->_h_free_align(reg_buf);
354	        reg_buf = NULL;
355	    }
356	#endif
357	
358	#if defined(USE_DRIVER_LOCK)
359		if (sdio_bus_lock) {
360			g_h.funcs->_h_destroy_mutex(sdio_bus_lock);
361			sdio_bus_lock = NULL;
362		}
363	#endif
364	
365		// free memory allocated in double buffering structs
366	#if H_SDIO_HOST_RX_MODE != H_SDIO_HOST_STREAMING_MODE
367	#  define H_DOUBLE_BUF_FREE(p)  sdio_buffer_free(p)
368	#else
369	#  define H_DOUBLE_BUF_FREE(p)  g_h.funcs->_h_free_align(p)
370	#endif
371		if (double_buf.buffer[0].buf) {
372			ESP_LOGI(TAG, "free buffer[0] %p", double_buf.buffer[0].buf);
373			H_DOUBLE_BUF_FREE(double_buf.buffer[0].buf);
374			double_buf.buffer[0].buf = NULL;
375			double_buf.buffer[0].buf_size = 0;
376		}
377		if (double_buf.buffer[1].buf) {
378			ESP_LOGI(TAG, "free buffer[1] %p", double_buf.buffer[1].buf);
379			H_DOUBLE_BUF_FREE(double_buf.buffer[1].buf);
380			double_buf.buffer[1].buf = NULL;
381			double_buf.buffer[1].buf_size = 0;
382		}
383	#undef H_DOUBLE_BUF_FREE
384		/* Reset double_buf state for clean reinitialization */
385		double_buf.read_index = -1;
386		double_buf.read_data_len = 0;
387		double_buf.write_index = 0;
388	
389		/* Reset SDIO counters */
390		sdio_tx_buf_count = 0;
391		sdio_rx_byte_count = 0;
392		mempool_oom_logged = false;
393		sdio_start_write_thread = false;
394	
395		sdio_mempool_destroy();
396		if (bus_handle) {
397			/* Free DMA aligned buffer before bus deinit */
398			g_h.funcs->_h_sdio_card_deinit(bus_handle);
399			g_h.funcs->_h_bus_deinit(bus_handle);
400		}
401		sdio_handle = NULL;
402	}
