404	static int sdio_generate_slave_intr(uint8_t intr_no)
405	{
406		uint8_t intr_mask = BIT(intr_no + ESP_SDIO_CONF_OFFSET);
407	
408		if (intr_no >= BIT(ESP_MAX_HOST_INTERRUPT)) {
409			ESP_LOGE(TAG,"Invalid slave interrupt number");
410			return ESP_ERR_INVALID_ARG;
411		}
412	
413		return g_h.funcs->_h_sdio_write_reg(sdio_handle, HOST_TO_SLAVE_INTR, &intr_mask,
414			sizeof(intr_mask), ACQUIRE_LOCK);
415	}
