429	static int sdio_get_tx_buffer_num(uint32_t *tx_num, bool is_lock_needed)
430	{
431		uint32_t len = 0;
432		int ret = 0;
433	
434		ret = g_h.funcs->_h_sdio_read_reg(sdio_handle, ESP_SLAVE_TOKEN_RDATA, (uint8_t *)&len,
435			sizeof(len), is_lock_needed);
436	
437		if (ret) {
438			ESP_LOGE(TAG, "%s: err: %d", __func__, ret);
439			return ret;
440		}
441	
442		len = (len >> 16) & ESP_TX_BUFFER_MASK;
443		len = (len + ESP_TX_BUFFER_MAX - sdio_tx_buf_count) % ESP_TX_BUFFER_MAX;
444	
445		*tx_num = len;
446	
447		return ret;
448	}
