459	static inline bool sdio_pkt_len_reg_is_bus_fault(uint32_t reg_val)
460	{
461		if (reg_val != UINT32_MAX)
462			return false;
463	
464		ESP_LOGE(TAG, "PKT_LEN reg reads 0x%08"PRIx32" (all 32 bits set): SDIO bus fault",
465				reg_val);
466		return true;
467	}
