554	#define MAX_BUFF_FETCH_PERIODICITY 30000
555	
556	static int sdio_is_write_buffer_available(uint32_t buf_needed)
557	{
558		static uint32_t buf_available = 0;
559		uint8_t retry = MAX_WRITE_BUF_RETRIES;
560		uint32_t max_retry_sdio_not_responding = 2;
561		uint32_t interval_us = 400;
562	
563		/*If buffer needed are less than buffer available
564		  then only read for available buffer number from slave*/
565		if (buf_available < buf_needed) {
566			while (retry) {
567				if (sdio_get_tx_buffer_num(&buf_available, ACQUIRE_LOCK) ==
568						ESP_HOSTED_SDIO_UNRESPONSIVE_CODE) {
569					max_retry_sdio_not_responding--;
570					/* restart the host to avoid the sdio locked out state */
571	
572					if (!max_retry_sdio_not_responding) {
573						ESP_LOGE(TAG, "%s: SDIO slave unresponsive", __func__);
574						g_h.funcs->_h_event_post(ESP_HOSTED_EVENT,
575								ESP_HOSTED_EVENT_TRANSPORT_FAILURE,
576								NULL, 0, HOSTED_BLOCK_MAX);
577	#if H_TRANSPORT_RESTART_ON_FAILURE
578						g_h.funcs->_h_restart_host();
579	#endif
580						return BUFFER_UNAVAILABLE;
581					}
582					continue;
583				}
584	
585				if (buf_available < buf_needed) {
586	
587					ESP_LOGV(TAG, "Retry get write buffers %d", retry);
588					retry--;
589	
590					g_h.funcs->_h_usleep(interval_us);
591					if (interval_us < MAX_BUFF_FETCH_PERIODICITY) {
592						interval_us += 400;
593					}
594					continue;
595				}
596				break;
597			}
598		}
599	
600		if (buf_available >= buf_needed)
601			buf_available -= buf_needed;
602	
603		if (!retry) {
604			/* No buffer available at slave */
605			return BUFFER_UNAVAILABLE;
606		}
607	
608		return BUFFER_AVAILABLE;
609	}
