611	static void sdio_write_task(void const* pvParameters)
612	{
613		uint16_t len = 0;
614		uint8_t *sendbuf = NULL;
615		void (*free_func)(void* ptr) = NULL;
616		struct esp_payload_header * payload_header = NULL;
617		uint8_t * payload  = NULL;
618		interface_buffer_handle_t buf_handle = {0};
619		int retries = 0;
620	
621		int ret = 0;
622		uint8_t *pos = NULL;
623		uint32_t data_left;
624		uint32_t len_to_send;
625		uint32_t buf_needed;
626		uint8_t tx_needed = 1;
627		uint8_t flag = 0;
628	
629		while (!sdio_start_write_thread)
630			g_h.funcs->_h_msleep(10);
631	
632		for (;;) {
633			/* Check if higher layers have anything to transmit */
634			g_h.funcs->_h_get_semaphore(sem_to_slave_queue, HOSTED_BLOCK_MAX);
635	
636			/* Tx msg is present as per sem */
637			if (g_h.funcs->_h_dequeue_item(to_slave_queue[PRIO_Q_SERIAL], &buf_handle, 0))
638				if (g_h.funcs->_h_dequeue_item(to_slave_queue[PRIO_Q_BT], &buf_handle, 0))
639					if (g_h.funcs->_h_dequeue_item(to_slave_queue[PRIO_Q_OTHERS], &buf_handle, 0)) {
640						tx_needed = 0; /* No Tx msg */
641					}
642	
643			if (tx_needed) {
644				len = buf_handle.payload_len;
645				flag = buf_handle.flag;
646			}
647	
648			if (!flag && !len) {
649				ESP_LOGE(TAG, "%s: Empty len", __func__);
650				goto done;
651			}
652	#if ESP_PKT_STATS
653			if (buf_handle.if_type == ESP_STA_IF)
654				pkt_stats.sta_tx_trans_in++;
655	#endif
656	
657			if (!buf_handle.payload_zcopy) {
658				sendbuf = sdio_buffer_alloc(MEMSET_REQUIRED);
659				free_func = sdio_buffer_free;
660			} else {
661				sendbuf = buf_handle.payload;
662				free_func = buf_handle.free_buf_handle;
663			}
664	
665			if (!sendbuf) {
666				if (!mempool_oom_logged) {
667					ESP_LOGW(TAG, "mempool OOM start (TX)");
668					mempool_oom_logged = true;
669				}
670				free_func = NULL;
671	#if ESP_PKT_STATS
672				if (buf_handle.if_type == ESP_STA_IF)
673					pkt_stats.sta_tx_out_drop++;
674	#endif
675				goto done;
676			}
677	
678			/* Non-zerocopy alloc just succeeded -> pool has space.
679			 * Zerocopy path doesn't touch the pool, so doesn't signal end. */
680			if (!buf_handle.payload_zcopy && mempool_oom_logged) {
681				ESP_LOGW(TAG, "mempool OOM end");
682				mempool_oom_logged = false;
683			}
684	
685			if (buf_handle.payload_len > MAX_SDIO_BUFFER_SIZE - sizeof(struct esp_payload_header)) {
686				ESP_LOGE(TAG, "Pkt len [%u] > Max [%u]. Drop",
687						buf_handle.payload_len, MAX_SDIO_BUFFER_SIZE - sizeof(struct esp_payload_header));
688				goto done;
689			}
690	
691			/* Form Tx header */
692			payload_header = (struct esp_payload_header *) sendbuf;
693			payload  = sendbuf + sizeof(struct esp_payload_header);
694	
695			payload_header->len = htole16(len);
696			payload_header->offset = htole16(sizeof(struct esp_payload_header));
697			payload_header->if_type = buf_handle.if_type;
698			payload_header->if_num = buf_handle.if_num;
699			payload_header->seq_num = htole16(buf_handle.seq_num);
700			payload_header->flags = buf_handle.flag;
701	
702			UPDATE_HEADER_TX_PKT_NO(payload_header);
703	
704			if (payload_header->if_type == ESP_HCI_IF) {
705				// special handling for HCI
706				if (!buf_handle.payload_zcopy) {
707					// copy first byte of payload into header
708					payload_header->hci_pkt_type = buf_handle.payload[0];
709					// adjust actual payload len
710					len -= 1;
711					payload_header->len = htole16(len);
712					g_h.funcs->_h_memcpy(payload, &buf_handle.payload[1], len);
713				}
714			} else
715			if (!buf_handle.payload_zcopy)
716				g_h.funcs->_h_memcpy(payload, buf_handle.payload, len);
717	
718	#if H_SDIO_CHECKSUM
719			payload_header->checksum = htole16(compute_checksum(sendbuf,
720				sizeof(struct esp_payload_header) + len));
721	#endif
722	
723			buf_needed = (len + sizeof(struct esp_payload_header) + ESP_RX_BUFFER_SIZE - 1)
724				/ ESP_RX_BUFFER_SIZE;
725	
726			SDIO_DRV_LOCK();
727	
728			ret = sdio_is_write_buffer_available(buf_needed);
729			if (ret != BUFFER_AVAILABLE) {
730				ESP_LOGV(TAG, "no SDIO write buffers on slave device");
731	#if ESP_PKT_STATS
732				if (payload_header->if_type == ESP_STA_IF)
733					pkt_stats.sta_tx_out_drop++;
734	#endif
735				goto unlock_done;
736			}
737	
738			pos = sendbuf;
739			data_left = len + sizeof(struct esp_payload_header);
740	
741			ESP_HEXLOGV("bus_TX", sendbuf, data_left, 32);
742	
743			len_to_send = 0;
744			retries = 0;
745			do {
746				len_to_send = data_left;
747	
748	#if H_SDIO_TX_BLOCK_ONLY_XFER
749				/* Extend the transfer length to do block only transfers.
750				 * This is safe as slave only reads up to data_left, which
751				 * is not changed here. Rest of data is discarded by
752				 * slave.
753				 */
754				uint32_t block_send_len = ((len_to_send + ESP_BLOCK_SIZE - 1) / ESP_BLOCK_SIZE) * ESP_BLOCK_SIZE;
755	
756				ret = g_h.funcs->_h_sdio_write_block(sdio_handle, ESP_SLAVE_CMD53_END_ADDR - data_left,
757					pos, block_send_len, ACQUIRE_LOCK);
758	#else
759				ret = g_h.funcs->_h_sdio_write_block(sdio_handle, ESP_SLAVE_CMD53_END_ADDR - data_left,
760					pos, len_to_send, ACQUIRE_LOCK);
761	#endif
762				if (ret) {
763					ESP_LOGE(TAG, "%s: %d: Failed to send data: %d %ld %ld", __func__,
764						retries, ret, len_to_send, data_left);
765					retries++;
766					if (retries < MAX_SDIO_WRITE_RETRY) {
767						ESP_LOGD(TAG, "retry");
768						continue;
769					} else {
770						SDIO_DRV_UNLOCK();
771						ESP_LOGE(TAG, "Unrecoverable host sdio state");
772						g_h.funcs->_h_event_post(ESP_HOSTED_EVENT,
773								ESP_HOSTED_EVENT_TRANSPORT_FAILURE,
774								NULL, 0, HOSTED_BLOCK_MAX);
775	#if H_TRANSPORT_RESTART_ON_FAILURE
776						g_h.funcs->_h_restart_host();
777	#endif
778						goto done;
779					}
780				}
781	
782				data_left -= len_to_send;
783				pos += len_to_send;
784			} while (data_left);
785	
786			sdio_tx_buf_count += buf_needed;
787			sdio_tx_buf_count = sdio_tx_buf_count % ESP_TX_BUFFER_MAX;
788	
789	#if ESP_PKT_STATS
790			if (buf_handle.if_type == ESP_STA_IF)
791				pkt_stats.sta_tx_out++;
792	#endif
793	
794	unlock_done:
795			SDIO_DRV_UNLOCK();
796	done:
797			if (len && !buf_handle.payload_zcopy) {
798				/* free allocated buffer, only if zerocopy is not requested */
799				H_FREE_PTR_WITH_FUNC(buf_handle.free_buf_handle, buf_handle.priv_buffer_handle);
800			}
801			H_FREE_PTR_WITH_FUNC(free_func, sendbuf);
802		}
803	}
804	
805	static int is_valid_sdio_rx_packet(uint8_t *rxbuff_a, uint16_t *len_a, uint16_t *offset_a)
806	{
807		struct esp_payload_header * h = (struct esp_payload_header *)rxbuff_a;
808		uint16_t len = 0, offset = 0;
809	#if H_SDIO_CHECKSUM
810		uint16_t rx_checksum = 0, checksum = 0;
811	#endif
812		uint8_t is_wakeup_pkt = 0;
813	
814		UPDATE_HEADER_RX_PKT_NO(h);
815		if (!h || !len_a || !offset_a)
816			return 0;
817	
818		/* Fetch length and offset from payload header */
819		len = le16toh(h->len);
820		offset = le16toh(h->offset);
821		is_wakeup_pkt = h->flags & FLAG_WAKEUP_PKT;
822	
823		if (is_wakeup_pkt && len<1500) {
824			ESP_LOGI(TAG, "Host wakeup triggered, len: %u ", len);
825			ESP_HEXLOGD("Wakeup_pkt", rxbuff_a+offset, len, H_MIN(len,128));
826		}
827	
828		if ((!len) ||
829			(len > MAX_PAYLOAD_SIZE) ||
830			(offset != sizeof(struct esp_payload_header))) {
831	
832			/* Free up buffer, as one of following -
833			 * 1. no payload to process
834			 * 2. input packet size > driver capacity
835			 * 3. payload header size mismatch,
836			 * wrong header/bit packing?
837			 * */
838	
839			if (len) {
840				ESP_LOGE(TAG, "len[%u]>max[%u] OR offset[%u] != exp[%u], Drop",
841					len, MAX_PAYLOAD_SIZE, offset, sizeof(struct esp_payload_header));
842			}
843	
844			return 0;
845	
846		}
847	
848	#if H_SDIO_CHECKSUM
849		rx_checksum = le16toh(h->checksum);
850		h->checksum = 0;
851		checksum = compute_checksum((uint8_t*)h, len + offset);
852	
853		if (checksum != rx_checksum) {
854			ESP_LOGE(TAG, "SDIO RX rx_chksum[%u] != checksum[%u]. Drop.",
855					checksum, rx_checksum);
856			return 0;
857		}
858	#endif
859	
860	#if ESP_PKT_STATS
861		if (h->if_type == ESP_STA_IF)
862			pkt_stats.sta_rx_in++;
863	#endif
864	
865		*len_a = len;
866		*offset_a = offset;
867	
868		return 1;
869	}
