871	// pushes received packet data on to rx queue
872	static esp_err_t sdio_push_pkt_to_queue(uint8_t * rxbuff, uint16_t len, uint16_t offset)
873	{
874		uint8_t pkt_prio = PRIO_Q_OTHERS;
875		struct esp_payload_header *h= NULL;
876		interface_buffer_handle_t buf_handle;
877	
878		h = (struct esp_payload_header *)rxbuff;
879	
880		memset(&buf_handle, 0, sizeof(interface_buffer_handle_t));
881	
882		buf_handle.priv_buffer_handle = rxbuff;
883		buf_handle.free_buf_handle    = sdio_buffer_free;
884		buf_handle.payload_len        = len;
885		buf_handle.if_type            = h->if_type;
886		buf_handle.if_num             = h->if_num;
887		buf_handle.payload            = rxbuff + offset;
888		buf_handle.seq_num            = le16toh(h->seq_num);
889		buf_handle.flag               = h->flags;
890	
891		if (buf_handle.if_type == ESP_SERIAL_IF)
892			pkt_prio = PRIO_Q_SERIAL;
893		else if (buf_handle.if_type == ESP_HCI_IF)
894			pkt_prio = PRIO_Q_BT;
895		/* else OTHERS by default */
896	
897		if( (!from_slave_queue[pkt_prio]) || (!sem_from_slave_queue)) {
898			ESP_LOGI(TAG, "uninitialised from_slave_queue or sem_from_slave_queue");
899			return ESP_FAIL;
900		}
901	
902		g_h.funcs->_h_queue_item(from_slave_queue[pkt_prio], &buf_handle, HOSTED_BLOCK_MAX);
903		g_h.funcs->_h_post_semaphore(sem_from_slave_queue);
904	
905		return ESP_OK;
906	}
