908	/**
909	 * These function definitions depend on whether we are in SDIO
910	 * streaming mode or not.
911	 */
912	#if H_SDIO_HOST_RX_MODE != H_SDIO_HOST_STREAMING_MODE
913	// SDIO packet mode
914	// return a buffer big enough to contain the data
915	static inline uint8_t * sdio_rx_get_buffer(uint32_t len)
916	{
917		int index = double_buf.write_index;
918		uint8_t ** buf = &double_buf.buffer[index].buf;
919	
920		*buf = (uint8_t *)sdio_buffer_alloc(MEMSET_REQUIRED);
921		double_buf.buffer[index].buf_size = len;
922	
923		return *buf;
924	}
