926	// this frees the buffer *before* it is queued
927	static void sdio_rx_free_buffer(uint8_t * buf)
928	{
929		sdio_buffer_free(buf);
930	}
931	
932	// push buffer on to the queue
933	static esp_err_t sdio_push_data_to_queue(uint8_t * buf, uint32_t buf_len)
934	{
935		uint16_t len = 0;
936		uint16_t offset = 0;
937	
938		/* Drop packet if no processing needed */
939		if (!is_valid_sdio_rx_packet(buf, &len, &offset)) {
940			/* Free up buffer, as one of following -
941			 * 1. no payload to process
942			 * 2. input packet size > driver capacity
943			 * 3. payload header size mismatch,
944			 * wrong header/bit packing?
945			 * */
946			ESP_LOGW(TAG, "Dropping packet");
947			sdio_buffer_free(buf);
948			return ESP_FAIL;
949		}
950	
951		if (sdio_push_pkt_to_queue(buf, len, offset)) {
952			ESP_LOGE(TAG, "Failed to push Rx packet to queue");
953			return ESP_FAIL;
954		}
955	
956		return ESP_OK;
957	}
958	#else // H_SDIO_HOST_STREAMING_MODE
959	// SDIO streaming mode
960	// return a buffer big enough to contain the data
961	static uint8_t * sdio_rx_get_buffer(uint32_t len)
962	{
963	#if H_SDIO_RX_BLOCK_ONLY_XFER
964		// we need to allocate enough memory to hold the padded data
965		len = ((len + ESP_BLOCK_SIZE - 1) / ESP_BLOCK_SIZE) * ESP_BLOCK_SIZE;
966	#endif
967	
968		// (re)allocate a write buffer big enough to contain the data stream
969		int index = double_buf.write_index;
970		uint8_t ** buf = &double_buf.buffer[index].buf;
971	
972		if (len > double_buf.buffer[index].buf_size) {
973			/* Allocate the larger buffer BEFORE freeing the old one. On a transient
974			 * heap shortage we degrade gracefully — keep the old buffer, leave the
975			 * slot consistent, and return NULL so the caller drops this read (the
976			 * slave resends / the RPC retries). This mirrors the mempool OOM
977			 * handling in sdio_push_data_to_queue() and replaces a hard assert that
978			 * crashed the host on transient memory pressure. */
979			uint8_t *newbuf = (uint8_t *)g_h.funcs->_h_malloc_align(len, HOSTED_MEM_ALIGNMENT_64);
980			if (!newbuf) {
981				ESP_LOGW(TAG, "RX buffer alloc failed (len=%lu); dropping read", (unsigned long)len);
982				return NULL;
983			}
984			if (*buf) {
985				// free the old (smaller) buffer now that the new one is secured
986				g_h.funcs->_h_free_align(*buf);
987			}
988			*buf = newbuf;
989			double_buf.buffer[index].buf_size = len;
990			ESP_LOGD(TAG, "buf %d size: %ld", index, double_buf.buffer[index].buf_size);
991		}
992		return *buf;
993	}
