997	{
998		// no op - keep the allocated static buffer as it is
999	}
1000	
1001	// extract packets from the stream and push on to the queue
1002	static esp_err_t sdio_push_data_to_queue(uint8_t * buf, uint32_t buf_len)
1003	{
1004		uint8_t * pkt_rxbuff = NULL;
1005		uint16_t len = 0;
1006		uint16_t offset = 0;
1007		uint32_t packet_size;
1008	
1009		// break up the data stream into packets to send to the queue
1010		do {
1011			if (!is_valid_sdio_rx_packet(buf, &len, &offset)) {
1012				/* Have to drop packets in the stream as we cannot decode
1013				 * them after this error */
1014				ESP_LOGE(TAG, "Dropping packet(s) from stream");
1015				/* TODO: Free by caller? */
1016				return ESP_FAIL;
1017			}
1018			/* Allocate rx buffer */
1019			pkt_rxbuff = sdio_buffer_alloc(MEMSET_REQUIRED);
1020			if (!pkt_rxbuff) {
1021				if (!mempool_oom_logged) {
1022					ESP_LOGW(TAG, "mempool OOM start (RX)");
1023					mempool_oom_logged = true;
1024				}
1025				/* Skip this packet and continue processing remaining stream data */
1026				packet_size = len + offset;
1027				if (packet_size > buf_len) {
1028					return ESP_FAIL;
1029				}
1030				buf_len -= packet_size;
1031				buf     += packet_size;
1032				continue;
1033			}
1034	
1035			if (mempool_oom_logged) {
1036				ESP_LOGW(TAG, "mempool OOM end");
1037				mempool_oom_logged = false;
1038			}
1039	
1040			packet_size = len + offset;
1041			if (packet_size > buf_len) {
1042				ESP_LOGE(TAG, "packet size[%lu]>[%lu] too big for remaining stream data",
1043						packet_size, buf_len);
1044				sdio_buffer_free(pkt_rxbuff);
1045				return ESP_FAIL;
1046			}
1047			memcpy(pkt_rxbuff, buf, packet_size);
1048	
1049			if (sdio_push_pkt_to_queue(pkt_rxbuff, len, offset)) {
1050				ESP_LOGI(TAG, "Failed to push a packet to queue from stream");
1051			}
1052	
1053			// move to the next packet in the stream
1054			buf_len -= packet_size;
1055			buf     += packet_size;
1056		} while (buf_len);
1057	
1058		return ESP_OK;
1059	}
1060	#endif
