1062	// double buffer task to transfer data from the current buffer to the queue
1063	static void sdio_data_to_rx_buf_task(void const* pvParameters)
1064	{
1065		uint8_t * buf;
1066		uint32_t len;
1067	
1068		ESP_LOGI(TAG, "sdio_data_to_rx_buf_task started");
1069	
1070		while (1) {
1071			g_h.funcs->_h_get_semaphore(sem_double_buf_xfer_data, HOSTED_BLOCK_MAX);
1072	
1073			if (double_buf.read_index < 0) {
1074				ESP_LOGE(TAG, "invalid double buf read_index");
1075				continue;
1076			}
1077	
1078			buf = double_buf.buffer[double_buf.read_index].buf;
1079			len = double_buf.read_data_len;
1080	
1081			if (sdio_push_data_to_queue(buf, len))
1082				ESP_LOGE(TAG, "Failed to push data to rx queue");
1083	
1084	#if H_SDIO_HOST_RX_MODE != H_SDIO_HOST_STREAMING_MODE
1085			double_buf.buffer[double_buf.read_index].buf = NULL;
1086	#endif
1087			// finished sending data: reset read_index
1088			double_buf.read_index = -1;
1089		}
1090	}
