1134	static void sdio_read_task(void const* pvParameters)
1135	{
1136		esp_err_t res = ESP_OK;
1137		uint8_t *rxbuff = NULL;
1138		int ret;
1139		uint32_t len_from_slave;
1140	
1141		uint32_t data_left;
1142		uint32_t len_to_read;
1143		uint8_t *pos;
1144		uint32_t interrupts;
1145		bool pending = true;
1146	
1147	#if DO_COMBINED_REG_READ
1148		uint32_t *intr_index = NULL;
1149	#endif
1150	
1151		assert(sdio_handle);
1152	
1153		// wait for transport to be in reset state
1154		while (true) {
1155			g_h.funcs->_h_msleep(100);
1156			if (is_transport_rx_ready()) {
1157				break;
1158			}
1159		}
1160	#if H_HOST_USES_STATIC_NETIF
1161		create_static_netif();
1162	#endif
1163	
1164	
1165	#if DO_COMBINED_REG_READ
1166	    if (!reg_buf) {
1167		    reg_buf = g_h.funcs->_h_malloc_align(REG_BUF_LEN, HOSTED_MEM_ALIGNMENT_64);
1168		    assert(reg_buf);
1169	    }
1170	#endif
1171	
1172		// display which SDIO mode we are operating in
1173	#if H_SDIO_HOST_RX_MODE == H_SDIO_HOST_STREAMING_MODE
1174		ESP_LOGI(TAG, "SDIO Host operating in STREAMING MODE");
1175	#else
1176		ESP_LOGI(TAG, "SDIO Host operating in PACKET MODE");
1177	#endif
1178	
1179		ESP_LOGI(TAG, "Open data path at slave");
1180	
1181	
1182		sdio_generate_slave_intr(ESP_OPEN_DATA_PATH);
1183	
1184		for (;;) {
1185	
1186			if (!pending) {
1187				// wait for sdio interrupt from slave
1188				/* Always blocks: a finite wait is unusable here, as
1189				 * sdmmc_host_io_int_wait() logs any non-OK at ERROR. */
1190				ESP_LOGD(TAG, "--- Wait for SDIO intr ---");
1191				res = g_h.funcs->_h_sdio_wait_slave_intr(sdio_handle, HOSTED_BLOCK_MAX);
1192				ESP_LOGD(TAG, "--- SDIO intr received ---");
1193	
1194				if (res != ESP_OK) {
1195					ESP_LOGE(TAG, "wait_slave_intr error: %d", res);
1196					continue;
1197				}
1198			}
1199			pending = false;
1200	
1201			SDIO_DRV_LOCK();
1202	
1203	#if DO_COMBINED_REG_READ
1204			if (sdio_read_regs(reg_buf)) {
1205				ESP_LOGE(TAG, "failed to read registers");
1206	
1207				SDIO_DRV_UNLOCK();
1208				g_h.funcs->_h_event_post(ESP_HOSTED_EVENT,
1209						ESP_HOSTED_EVENT_TRANSPORT_FAILURE,
1210						NULL, 0, HOSTED_BLOCK_MAX);
1211	#if H_TRANSPORT_RESTART_ON_FAILURE
1212				ESP_LOGI(TAG, "Host is resetting itself, to avoid any sdio race condition");
1213				g_h.funcs->_h_restart_host();
1214	#endif
1215				continue;
1216			}
1217	
1218			intr_index = (uint32_t *)&reg_buf[INT_RAW_INDEX];
1219			interrupts = *intr_index;
1220	#else
1221			// clear slave interrupts
1222			if (sdio_get_intr(&interrupts)) {
1223				ESP_LOGE(TAG, "failed to read interrupt register");
1224	
1225				SDIO_DRV_UNLOCK();
1226				g_h.funcs->_h_event_post(ESP_HOSTED_EVENT,
1227						ESP_HOSTED_EVENT_TRANSPORT_FAILURE,
1228						NULL, 0, HOSTED_BLOCK_MAX);
1229	#if H_TRANSPORT_RESTART_ON_FAILURE
1230				ESP_LOGI(TAG, "Host is resetting itself, to avoid any sdio race condition");
1231				g_h.funcs->_h_restart_host();
1232	#endif
1233				continue;
1234			}
1235	#endif
1236			sdio_clear_intr(interrupts);
1237	
1238			ESP_LOGV(TAG, "Intr: %08"PRIX32, interrupts);
1239	
1240			/* Check all supported interrupts */
1241			if (BIT(SDIO_INT_START_THROTTLE) & interrupts)
1242				wifi_tx_throttling = 1;
1243	
1244			if (BIT(SDIO_INT_STOP_THROTTLE) & interrupts)
1245				wifi_tx_throttling = 0;
1246	
1247			if (!(BIT(SDIO_INT_NEW_PACKET) & interrupts)) {
1248	
1249				SDIO_DRV_UNLOCK();
1250				continue;
1251			}
1252	
1253	#if H_SDIO_HOST_RX_MODE == H_SDIO_ALWAYS_HOST_RX_MAX_TRANSPORT_SIZE
1254			/* Bypass the check to find the bytes to be read from slave to host
1255			 * always assume max transport size to be read.
1256			 * slave sdio driver will automatically pad the remaining bytes after
1257			 * actual written bytes till requested size from host
1258			 * This typically improves throughput for larger packet sizes
1259			 **/
1260			len_from_slave = MAX_TRANSPORT_BUFFER_SIZE;
1261	#else
1262			/* check the length to be read */
1263	#if DO_COMBINED_REG_READ
1264			uint32_t *read_len_index = (uint32_t *)&reg_buf[PACKET_LEN_INDEX];
1265			ret = sdio_get_len_from_slave(&len_from_slave, *read_len_index, ACQUIRE_LOCK);
1266	#else
1267			ret = sdio_get_len_from_slave(&len_from_slave, ACQUIRE_LOCK);
1268	#endif
1269			if (ret == ESP_ERR_INVALID_STATE) {
1270				SDIO_DRV_UNLOCK();
1271				g_h.funcs->_h_event_post(ESP_HOSTED_EVENT,
1272						ESP_HOSTED_EVENT_TRANSPORT_FAILURE,
1273						NULL, 0, HOSTED_BLOCK_MAX);
1274	#if H_TRANSPORT_RESTART_ON_FAILURE
1275				g_h.funcs->_h_restart_host();
1276	#endif
1277				continue;
1278			}
1279	
1280			if (ret || !len_from_slave) {
1281				SDIO_DRV_UNLOCK();
1282				continue;
1283			} else {
1284				ESP_LOGD(TAG, "len_from_slave: %ld", len_from_slave);
1285			}
1286	#endif
1287	
1288			/* Allocate rx buffer */
1289			rxbuff = sdio_rx_get_buffer(len_from_slave);
1290			if (!rxbuff) {
1291				pending = true;
1292				SDIO_DRV_UNLOCK();
1293				g_h.funcs->_h_msleep(SDIO_RX_ALLOC_RETRY_MS);
1294				continue;
1295			}
1296	
1297			data_left = len_from_slave;
1298			pos = rxbuff;
1299	
1300			do {
1301				len_to_read = data_left;
1302	
1303	#if H_SDIO_RX_BLOCK_ONLY_XFER
1304				/* Extend the transfer length to do block only transfers.
1305				 * This is safe as slave will pad data with 0, which we
1306				 * will ignore.
1307				 */
1308				uint32_t block_read_len = ((len_to_read + ESP_BLOCK_SIZE - 1) / ESP_BLOCK_SIZE) * ESP_BLOCK_SIZE;
1309				ret = g_h.funcs->_h_sdio_read_block(sdio_handle,
1310						ESP_SLAVE_CMD53_END_ADDR - data_left,
1311						pos, block_read_len, ACQUIRE_LOCK);
1312	#else
1313				ret = g_h.funcs->_h_sdio_read_block(sdio_handle,
1314						ESP_SLAVE_CMD53_END_ADDR - data_left,
1315						pos, len_to_read, ACQUIRE_LOCK);
1316	#endif
1317				if (ret) {
1318					ESP_LOGE(TAG, "%s: Failed to read data - %d %ld %ld",
1319						__func__, ret, len_to_read, data_left);
1320					sdio_rx_free_buffer(rxbuff);
1321					break;
1322				}
1323				data_left -= len_to_read;
1324				pos += len_to_read;
1325			} while (data_left);
1326	
1327			SDIO_DRV_UNLOCK();
1328	
1329			//TODO: unclear, on failure case
1330			//sdio_rx_byte_count += (len_from_slave-data_left);
1331			sdio_rx_byte_count += len_from_slave;
1332			sdio_rx_byte_count = sdio_rx_byte_count % ESP_RX_BYTE_MAX;
1333	
1334	#if H_SDIO_HOST_RX_MODE != H_SDIO_ALWAYS_HOST_RX_MAX_TRANSPORT_SIZE
1335			pending = true;
1336	#endif
1337	
1338			if (unlikely(ret))
1339				continue;
1340	
1341			if (double_buf.read_index < 0) {
1342				double_buf.read_index = double_buf.write_index;
1343				double_buf.read_data_len = len_from_slave;
1344				double_buf.write_index = (double_buf.write_index) ? 0 : 1;
1345				// trigger task to copy data to queue
1346				g_h.funcs->_h_post_semaphore(sem_double_buf_xfer_data);
1347			} else {
1348				// error: task to copy data to queue still running
1349				sdio_rx_free_buffer(rxbuff);
1350				ESP_LOGE(TAG, "task still writing Rx data to queue!");
1351				// don't send data to task, or update write_index
1352			}
1353		}
1354	}
1355	
1356	static void sdio_process_rx_task(void const* pvParameters)
1357	{
1358		interface_buffer_handle_t buf_handle_l = {0};
1359		interface_buffer_handle_t *buf_handle = NULL;
1360		int ret = 0;
1361	
1362		struct esp_priv_event *event = NULL;
1363	
1364		while (true) {
1365			g_h.funcs->_h_msleep(100);
1366			if (is_transport_rx_ready()) {
1367				break;
1368			}
1369		}
1370		ESP_LOGI(TAG, "Starting SDIO process rx task");
1371	
1372		while (1) {
1373			g_h.funcs->_h_get_semaphore(sem_from_slave_queue, HOSTED_BLOCK_MAX);
1374	
1375			if (g_h.funcs->_h_dequeue_item(from_slave_queue[PRIO_Q_SERIAL], &buf_handle_l, 0))
1376				if (g_h.funcs->_h_dequeue_item(from_slave_queue[PRIO_Q_BT], &buf_handle_l, 0))
1377					if (g_h.funcs->_h_dequeue_item(from_slave_queue[PRIO_Q_OTHERS], &buf_handle_l, 0)) {
1378						ESP_LOGI(TAG, "No element in any queue found");
1379						continue;
1380					}
1381	
1382			buf_handle = &buf_handle_l;
1383	
1384			ESP_LOGV(TAG, "bus_rx: iftype:%d", (int)buf_handle->if_type);
1385			ESP_HEXLOGV("bus_rx", buf_handle->priv_buffer_handle,
1386					buf_handle->payload_len+H_ESP_PAYLOAD_HEADER_OFFSET, 32);
1387	
1388			if (buf_handle->if_type == ESP_SERIAL_IF) {
1389				/* serial interface path */
1390				serial_rx_handler(buf_handle);
1391			} else if((buf_handle->if_type == ESP_STA_IF) ||
1392					(buf_handle->if_type == ESP_AP_IF)) {
1393	#if 1
1394				if (chan_arr[buf_handle->if_type] && chan_arr[buf_handle->if_type]->rx) {
1395					/* TODO : Need to abstract heap_caps_malloc */
1396					uint8_t * copy_payload = (uint8_t *)g_h.funcs->_h_malloc(buf_handle->payload_len);
1397					assert(copy_payload);
1398					assert(buf_handle->payload_len);
1399					assert(buf_handle->payload);
1400					memcpy(copy_payload, buf_handle->payload, buf_handle->payload_len);
1401					H_FREE_PTR_WITH_FUNC(buf_handle->free_buf_handle, buf_handle->priv_buffer_handle);
1402	
1403	#if ESP_PKT_STATS
1404					if (buf_handle->if_type == ESP_STA_IF)
1405						pkt_stats.sta_rx_out++;
1406	#endif
1407					ret = chan_arr[buf_handle->if_type]->rx(chan_arr[buf_handle->if_type]->api_chan,
1408							copy_payload, copy_payload, buf_handle->payload_len);
1409					// only free memory when using older versions of wifi-remote
1410	#ifndef ESP_WIFI_REMOTE_VERSION // not defined in older versions of wifi-remote
1411					if (unlikely(ret))
1412						HOSTED_FREE(copy_payload);
1413	#else
1414	#if ESP_WIFI_REMOTE_VERSION < ESP_WIFI_REMOTE_VERSION_VAL(1,3,1)
1415					if (unlikely(ret))
1416						HOSTED_FREE(copy_payload);
1417	#else
1418					(void)ret; // to silence 'unused variable' warning
1419	#endif
1420	#endif
1421				}
1422	#else
1423				if (chan_arr[buf_handle->if_type] && chan_arr[buf_handle->if_type]->rx) {
1424					chan_arr[buf_handle->if_type]->rx(chan_arr[buf_handle->if_type]->api_chan,
1425							buf_handle->payload, NULL, buf_handle->payload_len);
1426				}
1427	#endif
1428			} else if (buf_handle->if_type == ESP_PRIV_IF) {
1429				ESP_LOGI(TAG, "Received ESP_PRIV_IF type message");
1430				process_priv_communication(buf_handle);
1431				hci_drv_show_configuration();
1432				/* priv transaction received */
1433				ESP_LOGI(TAG, "Received INIT event");
1434	
1435				event = (struct esp_priv_event *) (buf_handle->payload);
1436				ESP_LOGI(TAG, "Event type: 0x%x", event->event_type);
1437				if (event->event_type != ESP_PRIV_EVENT_INIT) {
1438					/* User can reuse this type of transaction */
1439					ESP_LOGW(TAG, "Not an ESP_PRIV_EVENT_INIT event: 0x%x", event->event_type);
1440				}
1441				ESP_LOGI(TAG, "Write thread started");
1442				sdio_start_write_thread = true;
1443			} else if (buf_handle->if_type == ESP_HCI_IF) {
1444				hci_rx_handler(buf_handle->payload, buf_handle->payload_len);
1445			} else if (buf_handle->if_type == ESP_TEST_IF) {
1446	#if TEST_RAW_TP
1447				update_test_raw_tp_rx_len(buf_handle->payload_len +
1448					H_ESP_PAYLOAD_HEADER_OFFSET);
1449	#endif
1450			} else {
1451				ESP_LOGW(TAG, "unknown type %d ", buf_handle->if_type);
1452			}
1453	
1454			/* Free buffer handle */
1455			/* When buffer offloaded to other module, that module is
1456			 * responsible for freeing buffer. In case not offloaded or
1457			 * failed to offload, buffer should be freed here.
1458			 */
1459			if (!buf_handle->payload_zcopy) {
1460				H_FREE_PTR_WITH_FUNC(buf_handle->free_buf_handle,
1461					buf_handle->priv_buffer_handle);
1462			}
1463		}
1464	}
1465	
1466	void *bus_init_internal(void)
1467	{
1468		uint8_t prio_q_idx = 0;
1469	
1470		int tx_queue_size = DEFAULT_TO_SLAVE_QUEUE_SIZE;
1471		int rx_queue_size = DEFAULT_FROM_SLAVE_QUEUE_SIZE;
1472	
1473		// reset sdio tx and rx counters
1474		sdio_tx_buf_count = 0;
1475		sdio_rx_byte_count = 0;
1476	
1477		struct esp_hosted_sdio_config *psdio_config;
1478	
1479		// get queue sizes from transport config
1480		if (ESP_TRANSPORT_OK == esp_hosted_sdio_get_config(&psdio_config)) {
1481			tx_queue_size = psdio_config->tx_queue_size;
1482			rx_queue_size = psdio_config->rx_queue_size;
1483			if (!tx_queue_size) {
1484				tx_queue_size = DEFAULT_TO_SLAVE_QUEUE_SIZE;
1485				ESP_LOGW(TAG, "provided sdio tx queue size is zero! Setting to %d", tx_queue_size);
1486			}
1487			if (!rx_queue_size) {
1488				rx_queue_size = DEFAULT_FROM_SLAVE_QUEUE_SIZE;
1489				ESP_LOGW(TAG, "provided sdio rx queue size is zero! Setting to %d", rx_queue_size);
1490			}
1491		} else {
1492			ESP_LOGW(TAG, "failed to get SDIO transport config: using default values");
1493		}
1494	
1495		/* register callback */
1496	
1497	#if defined(USE_DRIVER_LOCK)
1498		sdio_bus_lock = g_h.funcs->_h_create_mutex();
1499		assert(sdio_bus_lock);
1500	#endif
1501	
1502		sem_to_slave_queue = g_h.funcs->_h_create_semaphore(tx_queue_size * MAX_PRIORITY_QUEUES);
1503		assert(sem_to_slave_queue);
1504		g_h.funcs->_h_get_semaphore(sem_to_slave_queue, 0);
1505	
1506		sem_from_slave_queue = g_h.funcs->_h_create_semaphore(rx_queue_size * MAX_PRIORITY_QUEUES);
1507		assert(sem_from_slave_queue);
1508		g_h.funcs->_h_get_semaphore(sem_from_slave_queue, 0);
1509	
1510		/* cleanup the semaphores */
1511	
1512	
1513		for (prio_q_idx=0; prio_q_idx<MAX_PRIORITY_QUEUES;prio_q_idx++) {
1514			/* Queue - rx */
1515			from_slave_queue[prio_q_idx] = g_h.funcs->_h_create_queue(rx_queue_size, sizeof(interface_buffer_handle_t));
1516			assert(from_slave_queue[prio_q_idx]);
1517	
1518			/* Queue - tx */
1519			to_slave_queue[prio_q_idx] = g_h.funcs->_h_create_queue(tx_queue_size, sizeof(interface_buffer_handle_t));
1520			assert(to_slave_queue[prio_q_idx]);
1521		}
1522	
1523		sdio_mempool_create(tx_queue_size, rx_queue_size);
1524	
1525		/* initialise SDMMC before starting read/write threads
1526		 * which depend on SDMMC*/
1527		sdio_handle = g_h.funcs->_h_bus_init();
1528		if (!sdio_handle) {
1529			ESP_LOGE(TAG, "could not create sdio handle, exiting\n");
1530			assert(sdio_handle);
1531		}
1532	
1533		// initialise double buffering structs
1534		memset(&double_buf, 0, sizeof(double_buf_t));
1535		double_buf.read_index = -1; // indicates we are not reading anything
1536		double_buf.write_index = 0; // we will write into the first buffer
1537	
1538		sem_double_buf_xfer_data = g_h.funcs->_h_create_semaphore(1);
1539		assert(sem_double_buf_xfer_data);
1540		g_h.funcs->_h_get_semaphore(sem_double_buf_xfer_data, 0);
1541	
1542		sdio_rx_buf_thread = g_h.funcs->_h_thread_create("sdio_rx_buf",
1543			DFLT_TASK_PRIO, RX_BUF_TASK_STACK_SIZE, sdio_data_to_rx_buf_task, NULL);
1544	
1545		sdio_read_thread = g_h.funcs->_h_thread_create("sdio_read",
1546			DFLT_TASK_PRIO, DFLT_TASK_STACK_SIZE, sdio_read_task, NULL);
1547	
1548		sdio_process_rx_thread = g_h.funcs->_h_thread_create("sdio_process_rx",
1549			DFLT_TASK_PRIO, DFLT_TASK_STACK_SIZE, sdio_process_rx_task, NULL);
1550	
