/****************************************************************************
 * esp_hosted_nuttx.h
 *
 * NuttX port of esp-hosted WiFi driver for ESP32-P4 + ESP32-C6.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __ESP_HOSTED_NUTTX_H
#define __ESP_HOSTED_NUTTX_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdint.h>
#include <stdbool.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* esp_hosted interface types */

#define ESP_INVALID_IF    0
#define ESP_STA_IF        1
#define ESP_AP_IF         2
#define ESP_SERIAL_IF     3
#define ESP_HCI_IF        4
#define ESP_PRIV_IF       5
#define ESP_TEST_IF       6
#define ESP_ETH_IF        7
#define ESP_MAX_IF        8

/* Payload header flags */

#define MORE_FRAGMENT           (1 << 0)
#define FLAG_WAKEUP_PKT         (1 << 1)

/* Payload header structure - matches esp_hosted_header.h */

struct esp_payload_header_s
{
  uint8_t  if_type:4;
  uint8_t  if_num:4;
  uint8_t  flags;
  uint16_t len;
  uint16_t offset;
  uint16_t checksum;
  uint16_t seq_num;
  uint8_t  throttle_cmd:2;
  uint8_t  reserved2:6;
  union
  {
    uint8_t reserved3;
    uint8_t hci_pkt_type;
    uint8_t priv_pkt_type;
  };
} __attribute__((packed));

#define ESP_PAYLOAD_HEADER_SIZE  sizeof(struct esp_payload_header_s)

/* SDIO slave register addresses */

#define ESP_SLAVE_SLCHOST_BASE    0x3FF55000

#define ESP_SLAVE_INT_RAW_REG     (ESP_SLAVE_SLCHOST_BASE + 0x50)
#define ESP_SLAVE_INT_CLR_REG     (ESP_SLAVE_SLCHOST_BASE + 0xD4)
#define ESP_HOST_INT_ENA_REG      (ESP_SLAVE_SLCHOST_BASE + 0xDC)
#define ESP_SLAVE_PACKET_LEN_REG  (ESP_SLAVE_SLCHOST_BASE + 0x60)
#define ESP_SLAVE_TOKEN_RDATA     (ESP_SLAVE_SLCHOST_BASE + 0x44)

#define ESP_SLAVE_SCRATCH_REG_0   (ESP_SLAVE_SLCHOST_BASE + 0x6C)
#define ESP_SLAVE_SCRATCH_REG_7   (ESP_SLAVE_SLCHOST_BASE + 0x8C)

#define HOST_TO_SLAVE_INTR        ESP_SLAVE_SCRATCH_REG_7

/* SDIO interrupt bits */

#define SDIO_INT_NEW_PACKET       (23)
#define SDIO_INT_START_THROTTLE   (7)
#define SDIO_INT_STOP_THROTTLE    (6)

/* SDIO constants */

#define ESP_SLAVE_CMD53_END_ADDR  0x1F800
#define ESP_SLAVE_LEN_MASK        0xFFFFF
#define ESP_BLOCK_SIZE            512
#define ESP_RX_BYTE_MAX           0x100000
#define ESP_RX_BUFFER_SIZE        1536
#define ESP_TX_BUFFER_MASK        0xFFF
#define ESP_TX_BUFFER_MAX         0x1000

/* SDIO CCCR registers */

#define SD_IO_CCCR_FN_ENABLE      0x02
#define SD_IO_CCCR_FN_READY       0x03
#define SD_IO_CCCR_INT_ENABLE     0x04
#define SD_IO_CCCR_BUS_WIDTH      0x07
#define SD_IO_CCCR_BLKSIZEL       0x10
#define SD_IO_CCCR_BLKSIZEH       0x11

/* SDIO function numbers */

#define SDIO_FUNC_0               0
#define SDIO_FUNC_1               1

/* Max payload size */

#define MAX_PAYLOAD_SIZE          (ESP_RX_BUFFER_SIZE - ESP_PAYLOAD_HEADER_SIZE)

/* Priv event types */

#define ESP_PRIV_EVENT_INIT       1

/****************************************************************************
 * Public Types
 ****************************************************************************/

/* Private event structure */

struct esp_priv_event_s
{
  uint8_t event_type;
  uint8_t event_data[];
} __attribute__((packed));

/* Priv data: capabilities */

struct esp_priv_caps_s
{
  uint8_t type;
  uint8_t len;
  union
  {
    uint32_t cap;
    uint8_t raw[0];
  };
} __attribute__((packed));

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

#ifdef CONFIG_ESP32P4_WIFI_HOSTED

/****************************************************************************
 * Name: esp_hosted_sdio_init
 *
 * Description:
 *   Initialize SDIO hardware and establish communication with ESP32-C6.
 *
 * Returned Value:
 *   0 on success, negative errno on failure.
 *
 ****************************************************************************/

int esp_hosted_sdio_init(void);

/****************************************************************************
 * Name: esp_hosted_sdio_send
 *
 * Description:
 *   Send data over SDIO to ESP32-C6.
 *
 ****************************************************************************/

int esp_hosted_sdio_send(uint8_t if_type, uint8_t if_num,
                         const uint8_t *data, uint16_t len);

/****************************************************************************
 * Name: esp_hosted_sdio_recv
