int esp_hosted_wifi_init(void);

#endif /* CONFIG_ESP32P4_WIFI_HOSTED */
#endif /* __ESP_HOSTED_NUTTX_H */

/****************************************************************************
 * esp_hosted_sdio.c
 *
 * SDIO transport layer for esp-hosted protocol.
 * ESP32-P4 (host) <-> SDIO <-> ESP32-C6 (WiFi co-processor)
 *
 * This implements the SDIO communication protocol used by esp-hosted,
 * including card initialization, register access, and block transfers.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <nuttx/semaphore.h>
#include <debug.h>
#include <errno.h>
#include <string.h>
#include <stdio.h>

#include "esp_hosted_nuttx.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SDIO_TAG "sdio"
#define SDIO_ERR(...)   syslog(LOG_ERR, SDIO_TAG ": " __VA_ARGS__)
#define SDIO_INFO(...)  syslog(LOG_INFO, SDIO_TAG ": " __VA_ARGS__)
#define SDIO_DBG(...)   syslog(LOG_DEBUG, SDIO_TAG ": " __VA_ARGS__)

/* SDIO command definitions */

#define SDIO_CMD_GO_IDLE_STATE      0   /* CMD0  */
#define SDIO_CMD_SEND_OP_COND       5   /* CMD5  */
#define SDIO_CMD_SEND_RELATIVE_ADDR 3   /* CMD3  */
#define SDIO_CMD_SELECT_CARD        7   /* CMD7  */
#define SDIO_CMD_IO_RW_DIRECT      52   /* CMD52 */
#define SDIO_CMD_IO_RW_EXTENDED    53   /* CMD53 */

/* SDIO response types */

#define SDIO_RESP_NONE  0
#define SDIO_RESP_R4    1
#define SDIO_RESP_R6    2

/* CMD52 argument fields */

#define CMD52_FUNC(x)       (((x) & 0x7) << 28)
#define CMD52_OP_WRITE      (1 << 31)
#define CMD52_REG_ADDR(x)   (((x) & 0x1FFFF) << 9)

/* CMD53 argument fields */

#define CMD53_FUNC(x)       (((x) & 0x7) << 28)
#define CMD53_BLOCK_MODE    (1 << 27)
#define CMD53_OP_WRITE      (1 << 31)
#define CMD53_REG_ADDR(x)   (((x) & 0x1FFFF) << 9)
#define CMD53_COUNT(x)      (((x) & 0x1FF))

/* ESP32-P4 SDMMC register base address */

#define SDMMC_BASE          0x50083000
#define SDMMC_CTRL          (SDMMC_BASE + 0x00)
#define SDMMC_CLKDIV        (SDMMC_BASE + 0x08)
#define SDMMC_CLKSRC        (SDMMC_BASE + 0x0C)
#define SDMMC_CLKENA        (SDMMC_BASE + 0x10)
#define SDMMC_TMOUT         (SDMMC_BASE + 0x14)
#define SDMMC_CTYPE         (SDMMC_BASE + 0x18)
#define SDMMC_BLKSIZ        (SDMMC_BASE + 0x1C)
#define SDMMC_BYTCNT        (SDMMC_BASE + 0x20)
#define SDMMC_INTMASK       (SDMMC_BASE + 0x24)
#define SDMMC_CMDARG        (SDMMC_BASE + 0x28)
#define SDMMC_CMD           (SDMMC_BASE + 0x2C)
#define SDMMC_RESP0         (SDMMC_BASE + 0x30)
#define SDMMC_RINTSTS       (SDMMC_BASE + 0x44)
#define SDMMC_STATUS        (SDMMC_BASE + 0x48)
#define SDMMC_FIFOTH        (SDMMC_BASE + 0x4C)
#define SDMMC_FIFO          (SDMMC_BASE + 0x200)

/* GPIO base for ESP32-P4 */

#define GPIO_BASE           0x500E0000
#define GPIO_FUNC_OUT_SEL   (GPIO_BASE + 0x554)
#define GPIO_ENABLE_W1TS    (GPIO_BASE + 0x20)

/* SDMMC SLOT1 signal indices */

#define SDMMC_SLOT1_D0      58
#define SDMMC_SLOT1_D1      59
#define SDMMC_SLOT1_D2      60
#define SDMMC_SLOT1_D3      61
#define SDMMC_SLOT1_CLK     56
#define SDMMC_SLOT1_CMD     57

/* Timing */

#define SDIO_INIT_TIMEOUT_MS   1000
#define SDIO_CMD_TIMEOUT_MS    100
#define SDIO_DATA_TIMEOUT_MS   500

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct esp_sdio_dev_s
{
  mutex_t    lock;           /* Mutex for thread safety */
  uint32_t   freq;           /* Clock frequency in Hz */
  uint8_t    gpio_data_rdy;  /* DATA_READY GPIO from C6 */
  bool       initialized;    /* Initialization state */
  uint16_t   rca;            /* Relative Card Address */
  uint32_t   tx_buf_count;   /* TX buffer counter */
  uint32_t   rx_byte_count;  /* RX byte counter */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct esp_sdio_dev_s g_sdio;

/****************************************************************************
 * Private Functions - Low Level SDIO
 ****************************************************************************/

/****************************************************************************
 * Name: sdio_send_cmd
 *
 * Description:
 *   Send an SDIO command and optionally read the response.
 *
 ****************************************************************************/

static int sdio_send_cmd(uint32_t cmd, uint32_t arg,
                         uint32_t *resp, int resp_type)
{
  volatile uint32_t *cmd_reg  = (volatile uint32_t *)SDMMC_CMD;
  volatile uint32_t *arg_reg  = (volatile uint32_t *)SDMMC_CMDARG;
  volatile uint32_t *rint_reg = (volatile uint32_t *)SDMMC_RINTSTS;
  volatile uint32_t *status   = (volatile uint32_t *)SDMMC_STATUS;
  int timeout;

  /* Wait for controller not busy */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while ((*status & (1 << 9)) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  /* Clear pending interrupts */

  *rint_reg = 0xFFFFFFFF;

  /* Set argument */

  *arg_reg = arg;

  /* Build command register value */

  uint32_t cmd_val = (cmd & 0x3F) | (1 << 31);

  /* Set response type */

  switch (resp_type)
    {
      case SDIO_RESP_R4:
        cmd_val |= (1 << 6);
        break;
      case SDIO_RESP_R6:
        cmd_val |= (1 << 6);
        cmd_val |= (1 << 7);
        break;
      default:
        break;
    }

  /* For CMD0, send initialization sequence */

  if (cmd == 0)
    {
      cmd_val |= (1 << 10);
    }

  *cmd_reg = cmd_val;

  /* Wait for command done */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while ((*cmd_reg & (1 << 31)) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      SDIO_ERR("CMD timeout\n");
      return -ETIMEDOUT;
    }

  /* Check for errors */

  uint32_t rint = *rint_reg;

  if (rint & (1 << 1))
    {
      SDIO_ERR("CMD resp error\n");
      *rint_reg = (1 << 1);
      return -EIO;
    }

  if (rint & (1 << 8))
    {
      SDIO_ERR("CMD resp timeout\n");
      *rint_reg = (1 << 8);
      return -ETIMEDOUT;
    }

  if (rint & (1 << 2))
    {
      *rint_reg = (1 << 2);
    }

  /* Read response if requested */

  if (resp != NULL && resp_type != SDIO_RESP_NONE)
    {
      *resp = *((volatile uint32_t *)SDMMC_RESP0);
    }

  return OK;
}

/****************************************************************************
 * Name: sdio_cmd52_read
 *
 * Description:
 *   CMD52 - IO Read Direct (single byte)
 *
 ****************************************************************************/

static int sdio_cmd52_read(uint8_t func, uint32_t addr, uint8_t *data)
{
  uint32_t arg;
  uint32_t resp;
  int ret;

  arg = CMD52_FUNC(func) | CMD52_REG_ADDR(addr);

  ret = sdio_send_cmd(SDIO_CMD_IO_RW_DIRECT, arg, &resp, SDIO_RESP_R4);
  if (ret < 0)
    {
      return ret;
    }

  if (data != NULL)
    {
      *data = (resp >> 8) & 0xFF;
    }

  return OK;
}

/****************************************************************************
 * Name: sdio_cmd52_write
 *
 * Description:
 *   CMD52 - IO Write Direct (single byte)
 *
 ****************************************************************************/

static int sdio_cmd52_write(uint8_t func, uint32_t addr, uint8_t data,
                            uint8_t *resp_data)
{
  uint32_t arg;
  uint32_t resp;
  int ret;

  arg = CMD52_OP_WRITE | CMD52_FUNC(func) | CMD52_REG_ADDR(addr) | data;

  ret = sdio_send_cmd(SDIO_CMD_IO_RW_DIRECT, arg, &resp, SDIO_RESP_R4);
  if (ret < 0)
    {
      return ret;
    }

  if (resp_data != NULL)
    {
      *resp_data = (resp >> 8) & 0xFF;
    }

  return OK;
}

/****************************************************************************
 * Name: sdio_cmd53_read
 *
 * Description:
 *   CMD53 - IO Read Extended (block transfer)
 *
 ****************************************************************************/

static int sdio_cmd53_read(uint8_t func, uint32_t addr,
                           uint8_t *buf, uint16_t count)
{
  uint32_t arg;
  uint32_t resp;
  int ret;
  int i;
  int timeout;

  /* Configure block size and byte count */

  volatile uint32_t *blksiz = (volatile uint32_t *)SDMMC_BLKSIZ;
  volatile uint32_t *bytcnt = (volatile uint32_t *)SDMMC_BYTCNT;

  /* Align to block size for block transfers */

  uint32_t aligned_count = ((count + ESP_BLOCK_SIZE - 1) / ESP_BLOCK_SIZE)
                           * ESP_BLOCK_SIZE;
  *blksiz = aligned_count;
  *bytcnt = aligned_count;

  /* Build CMD53 argument: read, byte mode */

  arg = CMD53_FUNC(func) | CMD53_REG_ADDR(addr) | CMD53_COUNT(count);

  ret = sdio_send_cmd(SDIO_CMD_IO_RW_EXTENDED, arg, &resp, SDIO_RESP_R4);
  if (ret < 0)
    {
      return ret;
    }

  /* Wait for data ready (FIFO not empty) */

  volatile uint32_t *status = (volatile uint32_t *)SDMMC_STATUS;
  timeout = SDIO_DATA_TIMEOUT_MS;
  while ((*status & (1 << 4)) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  /* Read data from FIFO */

  volatile uint32_t *fifo = (volatile uint32_t *)SDMMC_FIFO;

  for (i = 0; i < (int)((aligned_count + 3) / 4); i++)
    {
      uint32_t word = *fifo;
      int j;
      for (j = 0; j < 4 && (i * 4 + j) < (int)count; j++)
        {
          buf[i * 4 + j] = (word >> (j * 8)) & 0xFF;
        }
    }

  return count;
}

/****************************************************************************
 * Name: sdio_cmd53_write
 *
 * Description:
 *   CMD53 - IO Write Extended (block transfer)
 *
 ****************************************************************************/

static int sdio_cmd53_write(uint8_t func, uint32_t addr,
                            const uint8_t *buf, uint16_t count)
{
  uint32_t arg;
  uint32_t resp;
  int ret;
  int i;

  /* Configure block size and byte count */

  volatile uint32_t *blksiz = (volatile uint32_t *)SDMMC_BLKSIZ;
  volatile uint32_t *bytcnt = (volatile uint32_t *)SDMMC_BYTCNT;

  /* Align to block size for block transfers */

  uint32_t aligned_count = ((count + ESP_BLOCK_SIZE - 1) / ESP_BLOCK_SIZE)
                           * ESP_BLOCK_SIZE;
  *blksiz = aligned_count;
  *bytcnt = aligned_count;

  /* Build CMD53 argument: write, byte mode */

  arg = CMD53_OP_WRITE | CMD53_FUNC(func) |
        CMD53_REG_ADDR(addr) | CMD53_COUNT(count);

  /* Write data to FIFO before sending command */

  volatile uint32_t *fifo = (volatile uint32_t *)SDMMC_FIFO;

  for (i = 0; i < (int)((aligned_count + 3) / 4); i++)
    {
      uint32_t word = 0;
      int j;
      for (j = 0; j < 4 && (i * 4 + j) < (int)count; j++)
        {
          word |= ((uint32_t)buf[i * 4 + j]) << (j * 8);
        }
      *fifo = word;
    }

  ret = sdio_send_cmd(SDIO_CMD_IO_RW_EXTENDED, arg, &resp, SDIO_RESP_R4);
  if (ret < 0)
    {
      return ret;
    }

  return count;
}

/****************************************************************************
 * Name: sdio_init_hw
 *
 * Description:
 *   Initialize the ESP32-P4 SDMMC hardware for SDIO communication.
 *
 ****************************************************************************/

static int sdio_init_hw(void)
{
  volatile uint32_t *clk_rst_reg;
  int timeout;
  uint32_t resp;
  int ret;

  SDIO_INFO("Initializing SDIO hardware\n");

  /* Step 1: Enable SDMMC peripheral clock */

  clk_rst_reg = (volatile uint32_t *)0x500E6004;
  *clk_rst_reg |= (1 << 12);
  SDIO_DBG("Clock enabled\n");

  /* Step 2: Configure GPIO pins for SDIO2 via GPIO matrix
   * Pin mapping:
   *   SD2 D0  = GPIO14
   *   SD2 D1  = GPIO15
   *   SD2 D2  = GPIO16
   *   SD2 D3  = GPIO17
   *   SD2 CLK = GPIO18
   *   SD2 CMD = GPIO19
   */

  volatile uint32_t *func_out;
  volatile uint32_t *enable;

  /* GPIO14 -> SDMMC SLOT1 D0 */

  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 14 * 4);
  *func_out = SDMMC_SLOT1_D0;
  enable = (volatile uint32_t *)(GPIO_ENABLE_W1TS);
  *enable = (1 << 14);

  /* GPIO15 -> SDMMC SLOT1 D1 */

  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 15 * 4);
  *func_out = SDMMC_SLOT1_D1;
  *enable = (1 << 15);

  /* GPIO16 -> SDMMC SLOT1 D2 */

  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 16 * 4);
  *func_out = SDMMC_SLOT1_D2;
  *enable = (1 << 16);

  /* GPIO17 -> SDMMC SLOT1 D3 */

  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 17 * 4);
  *func_out = SDMMC_SLOT1_D3;
  *enable = (1 << 17);

  /* GPIO18 -> SDMMC SLOT1 CLK */

  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 18 * 4);
  *func_out = SDMMC_SLOT1_CLK;
  *enable = (1 << 18);

  /* GPIO19 -> SDMMC SLOT1 CMD */

  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 19 * 4);
  *func_out = SDMMC_SLOT1_CMD;
  *enable = (1 << 19);

  SDIO_DBG("GPIO configured\n");

  /* Step 3: Reset the SDMMC controller */

  volatile uint32_t *ctrl = (volatile uint32_t *)SDMMC_CTRL;
  *ctrl = 0x7;
  up_mdelay(10);

  int rst_timeout = 100;
  while ((*ctrl & 0x7) && rst_timeout-- > 0)
    {
      up_mdelay(1);
    }

  SDIO_DBG("Controller reset done\n");

  /* Step 4: Configure clock for identification mode (400kHz) */

  volatile uint32_t *clkdiv = (volatile uint32_t *)SDMMC_CLKDIV;
  *clkdiv = (200 << 8) | 200;

  volatile uint32_t *clksrc = (volatile uint32_t *)SDMMC_CLKSRC;
  *clksrc = 0;

  volatile uint32_t *clkena = (volatile uint32_t *)SDMMC_CLKENA;
  *clkena = 0x1;

  volatile uint32_t *tmout = (volatile uint32_t *)SDMMC_TMOUT;
  *tmout = (0xFFFFFF << 8) | 0x64;

  volatile uint32_t *ctype = (volatile uint32_t *)SDMMC_CTYPE;
  *ctype = 0;

  /* Step 5: Send CMD0 (GO_IDLE_STATE) */

  ret = sdio_send_cmd(SDIO_CMD_GO_IDLE_STATE, 0, NULL, SDIO_RESP_NONE);
  if (ret < 0)
    {
      SDIO_ERR("CMD0 failed\n");
      return ret;
    }

  up_mdelay(10);

  /* Step 6: Send CMD5 (IO_SEND_OP_COND) to detect SDIO card */

  ret = sdio_send_cmd(SDIO_CMD_SEND_OP_COND, 0, &resp, SDIO_RESP_R4);
  if (ret < 0)
    {
      SDIO_ERR("CMD5 query failed\n");
      return ret;
    }

  SDIO_DBG("CMD5 query OK\n");

  /* Send CMD5 with voltage window */

  ret = sdio_send_cmd(SDIO_CMD_SEND_OP_COND, 0x00FF8000,
                      &resp, SDIO_RESP_R4);
  up_mdelay(10);

  /* Step 7: Send CMD3 (SEND_RELATIVE_ADDR) */

  ret = sdio_send_cmd(SDIO_CMD_SEND_RELATIVE_ADDR, 0, &resp, SDIO_RESP_R6);
  if (ret < 0)
    {
      SDIO_ERR("CMD3 failed: %d\n", ret);
      return ret;
    }

  g_sdio.rca = (resp >> 16) & 0xFFFF;
  SDIO_DBG("CMD3 done, RCA=0x%04x\n", g_sdio.rca);

  /* Step 8: Send CMD7 (SELECT_CARD) */

  ret = sdio_send_cmd(SDIO_CMD_SELECT_CARD,
                      ((uint32_t)g_sdio.rca) << 16,
                      &resp, SDIO_RESP_R6);
  if (ret < 0)
    {
      SDIO_ERR("CMD7 failed: %d\n", ret);
      return ret;
    }

  SDIO_DBG("CMD7 done\n");

  /* Step 9: Enable SDIO function 1 */

  ret = sdio_cmd52_write(0, SD_IO_CCCR_FN_ENABLE, 0x02, NULL);
  if (ret < 0)
    {
      SDIO_ERR("Failed to enable SDIO function 1: %d\n", ret);
      return ret;
    }

  /* Wait for function 1 to be ready */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while (timeout-- > 0)
    {
      uint8_t ready;
      ret = sdio_cmd52_read(0, SD_IO_CCCR_FN_READY, &ready);
      if (ret >= 0 && (ready & 0x02))
        {
          SDIO_INFO("SDIO function 1 ready\n");
          break;
        }
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      SDIO_ERR("SDIO function 1 not ready\n");
      return -ETIMEDOUT;
    }

  /* Step 10: Set bus width to 4-bit */

  ret = sdio_cmd52_write(0, SD_IO_CCCR_BUS_WIDTH, 0x02, NULL);
  if (ret < 0)
    {
      SDIO_WARN("Failed to set 4-bit bus width\n");
      /* Not fatal, continue with 1-bit mode */
    }
  else
    {
      SDIO_INFO("4-bit bus width enabled\n");
    }

  /* Step 11: Set block size for function 1 */

  ret = sdio_cmd52_write(0, SD_IO_CCCR_BLKSIZEL,
                         (ESP_BLOCK_SIZE & 0xFF), NULL);
  if (ret < 0)
    {
      SDIO_ERR("Failed to set block size low\n");
      return ret;
    }

  ret = sdio_cmd52_write(0, SD_IO_CCCR_BLKSIZEH,
                         ((ESP_BLOCK_SIZE >> 8) & 0xFF), NULL);
  if (ret < 0)
    {
      SDIO_ERR("Failed to set block size high\n");
      return ret;
    }

  /* Step 12: Increase clock speed to operational frequency */

  /* Source clock = 160MHz, target = 20MHz
   * Divider = 160MHz / 20MHz / 2 = 4
   */

  *clkdiv = (4 << 8) | 4;

  SDIO_INFO("SDIO hardware initialized OK\n");
  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp_hosted_sdio_init
 ****************************************************************************/

int esp_hosted_sdio_init(void)
{
  int ret;

  memset(&g_sdio, 0, sizeof(g_sdio));
  nxmutex_init(&g_sdio.lock);

  g_sdio.freq = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_FREQ;
  g_sdio.gpio_data_rdy = CONFIG_ESP32P4_WIFI_HOSTED_GPIO_DATA_RDY;

  /* Initialize SDIO hardware */

  ret = sdio_init_hw();
  if (ret < 0)
    {
      SDIO_ERR("SDIO hardware init failed: %d\n", ret);
      return ret;
    }

  g_sdio.initialized = true;
  g_sdio.tx_buf_count = 0;
  g_sdio.rx_byte_count = 0;

  return OK;
}

/****************************************************************************
 * Name: esp_hosted_sdio_read_reg
 ****************************************************************************/

int esp_hosted_sdio_read_reg(uint32_t addr, uint8_t *data, uint16_t size)
{
  int ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  nxmutex_lock(&g_sdio.lock);

  if (size == 1)
    {
      ret = sdio_cmd52_read(SDIO_FUNC_1, addr, data);
    }
  else if (size == 4)
    {
      /* Read 4 bytes using CMD53 */

      ret = sdio_cmd53_read(SDIO_FUNC_1, addr, data, 4);
    }
  else
    {
      ret = -EINVAL;
    }

  nxmutex_unlock(&g_sdio.lock);
  return ret;
}

/****************************************************************************
 * Name: esp_hosted_sdio_write_reg
 ****************************************************************************/

int esp_hosted_sdio_write_reg(uint32_t addr, uint8_t *data, uint16_t size)
{
  int ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  nxmutex_lock(&g_sdio.lock);

  if (size == 1)
    {
      ret = sdio_cmd52_write(SDIO_FUNC_1, addr, *data, NULL);
    }
  else if (size == 4)
    {
      /* Write 4 bytes using CMD53 */

      ret = sdio_cmd53_write(SDIO_FUNC_1, addr, data, 4);
    }
  else
    {
      ret = -EINVAL;
    }

  nxmutex_unlock(&g_sdio.lock);
  return ret;
}

/****************************************************************************
 * Name: esp_hosted_sdio_read_block
 ****************************************************************************/

int esp_hosted_sdio_read_block(uint32_t addr, uint8_t *data, uint16_t size)
{
  int ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  nxmutex_lock(&g_sdio.lock);
  ret = sdio_cmd53_read(SDIO_FUNC_1, addr, data, size);
  nxmutex_unlock(&g_sdio.lock);

  return ret;
}

/****************************************************************************
 * Name: esp_hosted_sdio_write_block
 ****************************************************************************/

int esp_hosted_sdio_write_block(uint32_t addr, const uint8_t *data,
                                uint16_t size)
{
  int ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  nxmutex_lock(&g_sdio.lock);
  ret = sdio_cmd53_write(SDIO_FUNC_1, addr, data, size);
  nxmutex_unlock(&g_sdio.lock);

  return ret;
}

/****************************************************************************
 * Name: esp_hosted_sdio_get_intr
 ****************************************************************************/

int esp_hosted_sdio_get_intr(uint32_t *interrupts)
{
  int ret;

  ret = esp_hosted_sdio_read_reg(ESP_SLAVE_INT_RAW_REG,
                                 (uint8_t *)interrupts, 4);
  return ret;
}

/****************************************************************************
 * Name: esp_hosted_sdio_clear_intr
 ****************************************************************************/

int esp_hosted_sdio_clear_intr(uint32_t interrupts)
{
  return esp_hosted_sdio_write_reg(ESP_SLAVE_INT_CLR_REG,
                                   (uint8_t *)&interrupts, 4);
}

/****************************************************************************
 * Name: esp_hosted_sdio_get_packet_len
 ****************************************************************************/

int esp_hosted_sdio_get_packet_len(uint32_t *len)
{
  int ret;

  ret = esp_hosted_sdio_read_reg(ESP_SLAVE_PACKET_LEN_REG,
                                 (uint8_t *)len, 4);
  if (ret < 0)
    {
      return ret;
    }

  *len &= ESP_SLAVE_LEN_MASK;

  /* Adjust for rolling counter */

  if (*len >= g_sdio.rx_byte_count)
    {
      *len = (*len + ESP_RX_BYTE_MAX - g_sdio.rx_byte_count)
             % ESP_RX_BYTE_MAX;
    }
  else
    {
      uint32_t temp = ESP_RX_BYTE_MAX - g_sdio.rx_byte_count;
      *len = temp + *len;
    }

  return OK;
}

/****************************************************************************
 * Name: esp_hosted_sdio_get_tx_buf_num
 ****************************************************************************/

int esp_hosted_sdio_get_tx_buf_num(uint32_t *tx_num)
{
  uint32_t len = 0;
  int ret;

  ret = esp_hosted_sdio_read_reg(ESP_SLAVE_TOKEN_RDATA,
                                 (uint8_t *)&len, 4);
  if (ret < 0)
    {
      return ret;
    }

  len = (len >> 16) & ESP_TX_BUFFER_MASK;
  len = (len + ESP_TX_BUFFER_MAX - g_sdio.tx_buf_count) % ESP_TX_BUFFER_MAX;

  *tx_num = len;
  return OK;
}

/****************************************************************************
 * Name: esp_hosted_sdio_generate_slave_intr
 ****************************************************************************/

int esp_hosted_sdio_generate_slave_intr(uint8_t intr_no)
{
  uint8_t intr_mask = (1 << intr_no);

  if (intr_no >= 8)
    {
      return -EINVAL;
    }

  return esp_hosted_sdio_write_reg(HOST_TO_SLAVE_INTR, &intr_mask, 1);
}

/****************************************************************************
 * Name: esp_hosted_sdio_update_rx_count
 ****************************************************************************/

void esp_hosted_sdio_update_rx_count(uint32_t len)
{
  g_sdio.rx_byte_count += len;
  g_sdio.rx_byte_count = g_sdio.rx_byte_count % ESP_RX_BYTE_MAX;
}

/****************************************************************************
 * Name: esp_hosted_sdio_update_tx_count
 ****************************************************************************/

void esp_hosted_sdio_update_tx_count(uint32_t buf_count)
{
  g_sdio.tx_buf_count += buf_count;
  g_sdio.tx_buf_count = g_sdio.tx_buf_count % ESP_TX_BUFFER_MAX;
}

/****************************************************************************
 * esp_hosted_wifi.c
 *
 * WiFi network device driver using esp-hosted protocol over SDIO.
 * Registers as wlan0 in NuttX networking stack.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/net/netdev.h>
#include <nuttx/wqueue.h>
#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <nuttx/semaphore.h>
#include <debug.h>
#include <errno.h>
#include <string.h>
#include <syslog.h>
#include <stdio.h>

#include "esp_hosted_nuttx.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define WIFI_TAG "wifi"
#define WIFI_ERR(...)  syslog(LOG_ERR, WIFI_TAG ": " __VA_ARGS__)
#define WIFI_INFO(...) syslog(LOG_INFO, WIFI_TAG ": " __VA_ARGS__)
#define WIFI_DBG(...)  syslog(LOG_DEBUG, WIFI_TAG ": " __VA_ARGS__)

/* Work queue timing */

#define WIFI_POLL_INTERVAL   MSEC2TICK(10)
#define WIFI_RX_POLL_FAST    MSEC2TICK(1)

/* Maximum scan results */

#define MAX_SCAN_RESULTS     16
#define MAX_SSID_LEN         32

/* ESP_OPEN_DATA_PATH interrupt number */

#define ESP_OPEN_DATA_PATH   0

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* WiFi driver private data */

struct esp_wifi_dev_s
{
  struct net_driver_s  netdev;           /* NuttX network device */
  struct work_s        pollwork;         /* Deferred poll work */
  bool                 ifup;            /* Interface is up */
  bool                 connected;       /* WiFi connected */
  bool                 transport_ready; /* Transport is ready */
  uint8_t              mac[6];          /* MAC address */
  uint8_t              rxbuf[2048];     /* Receive buffer */
  char                 ssid[MAX_SSID_LEN + 1]; /* Current SSID */
  char                 password[64];    /* Current password */
  uint8_t              status;          /* WiFi status */
  mutex_t              lock;            /* Thread safety */
  uint16_t             seq_num;         /* TX sequence number */
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int  esp_wifi_ifup(FAR struct net_driver_s *dev);
static int  esp_wifi_ifdown(FAR struct net_driver_s *dev);
static int  esp_wifi_transmit(FAR struct net_driver_s *dev);
static int  esp_wifi_txavail(FAR struct net_driver_s *dev);
#ifdef CONFIG_NETDEV_IOCTL
static int  esp_wifi_ioctl(FAR struct net_driver_s *dev, int cmd,
                           unsigned long arg);
#endif
static void esp_wifi_poll_work(FAR void *arg);
static void esp_wifi_process_rx(void);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct esp_wifi_dev_s g_wifi;

/****************************************************************************
 * Private Functions - WiFi RX/TX
 ****************************************************************************/

/****************************************************************************
 * Name: esp_wifi_process_rx
 *
 * Description:
 *   Process received data from SDIO and pass to network stack.
 *
 ****************************************************************************/

static void esp_wifi_process_rx(void)
{
  int ret;
  uint8_t if_type;
  uint8_t if_num;
  struct esp_payload_header_s *hdr;
  uint16_t len;
  uint16_t offset;

  /* Try to receive data from SDIO */

  ret = esp_hosted_sdio_recv(&if_type, &if_num,
                             g_wifi.rxbuf, sizeof(g_wifi.rxbuf));
  if (ret <= 0)
    {
      return;
    }

  /* Check if this is a data packet for STA interface */

  if (if_type != ESP_STA_IF)
    {
      if (if_type == ESP_PRIV_IF)
        {
          /* Handle private events (init, capabilities, etc.) */

          hdr = (struct esp_payload_header_s *)g_wifi.rxbuf;
          len = hdr->len;
          offset = hdr->offset;

          if (len > 0 && offset > 0)
            {
              uint8_t *payload = g_wifi.rxbuf + offset;
              struct esp_priv_event_s *event =
                (struct esp_priv_event_s *)payload;

              if (event->event_type == ESP_PRIV_EVENT_INIT)
                {
                  WIFI_INFO("Received INIT event from slave\n");
                  g_wifi.transport_ready = true;

                  /* Send OPEN_DATA_PATH to slave */

                  esp_hosted_sdio_generate_slave_intr(ESP_OPEN_DATA_PATH);
                }
            }
        }

      return;
    }

  /* This is a WiFi data packet */

  hdr = (struct esp_payload_header_s *)g_wifi.rxbuf;
  len = hdr->len;
  offset = hdr->offset;

  if (len == 0 || offset == 0 || len > MAX_PAYLOAD_SIZE)
    {
      WIFI_DBG("Invalid packet: len=%u offset=%u\n", len, offset);
      return;
    }

  /* Verify checksum */

  uint16_t rx_checksum = hdr->checksum;
  hdr->checksum = 0;
  uint16_t checksum = 0;
  uint8_t *p = g_wifi.rxbuf;
  int i;

  for (i = 0; i < (int)(len + offset); i++)
    {
      checksum += p[i];
    }

  if (rx_checksum != checksum)
    {
      WIFI_DBG("Checksum mismatch: rx=%u calc=%u\n", rx_checksum, checksum);
      /* Continue anyway for now */
    }

  /* Pass received packet to the network stack */

  g_wifi.netdev.d_buf = g_wifi.rxbuf + offset;
  g_wifi.netdev.d_len = len;

  WIFI_DBG("RX %d bytes\n", len);

  ipv4_input(&g_wifi.netdev);

  /* Reset buffer pointer */

  g_wifi.netdev.d_buf = NULL;
  g_wifi.netdev.d_len = 0;
}

/****************************************************************************
 * Private Functions - Network Device Callbacks
 ****************************************************************************/

/****************************************************************************
 * Name: esp_wifi_ifup
 ****************************************************************************/

static int esp_wifi_ifup(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing up WiFi interface\n");

  priv->ifup = true;

  /* Start periodic poll work */

  work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
             priv, WIFI_POLL_INTERVAL);

  return OK;
}

/****************************************************************************
 * Name: esp_wifi_ifdown
 ****************************************************************************/

static int esp_wifi_ifdown(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing down WiFi interface\n");

  work_cancel(LPWORK, &priv->pollwork);

  priv->ifup = false;
  return OK;
}

/****************************************************************************
 * Name: esp_wifi_transmit
 ****************************************************************************/

static int esp_wifi_transmit(FAR struct net_driver_s *dev)
{
  int ret;

  WIFI_DBG("TX %d bytes\n", dev->d_len);

  ret = esp_hosted_sdio_send(ESP_STA_IF, 0, dev->d_buf, dev->d_len);
  if (ret < 0)
    {
      WIFI_ERR("TX failed: %d\n", ret);
    }

  return ret;
}

/****************************************************************************
 * Name: esp_wifi_txavail
 ****************************************************************************/

static int esp_wifi_txavail(FAR struct net_driver_s *dev)
{
  if (dev->d_buf != NULL && dev->d_len > 0)
    {
      return esp_wifi_transmit(dev);
    }

  return OK;
}

/****************************************************************************
 * Name: esp_wifi_ioctl
 ****************************************************************************/

#ifdef CONFIG_NETDEV_IOCTL
static int esp_wifi_ioctl(FAR struct net_driver_s *dev, int cmd,
                          unsigned long arg)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;
  int ret = -ENOTTY;

  switch (cmd)
    {
      default:
        WIFI_DBG("Unknown ioctl 0x%x\n", cmd);
        break;
    }

  return ret;
}
#endif /* CONFIG_NETDEV_IOCTL */

/****************************************************************************
 * Name: esp_wifi_poll_work
 ****************************************************************************/

static void esp_wifi_poll_work(FAR void *arg)
{
  FAR struct esp_wifi_dev_s *priv = (FAR struct esp_wifi_dev_s *)arg;

  if (!priv->ifup)
    {
      return;
    }

  /* Process any pending RX data */

  esp_wifi_process_rx();

  /* Re-schedule poll work */

  if (priv->ifup)
    {
      work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
                 priv, WIFI_POLL_INTERVAL);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp_hosted_wifi_init
 ****************************************************************************/

int esp_hosted_wifi_init(void)
{
  int ret;

  WIFI_INFO("Initializing esp-hosted WiFi\n");

  memset(&g_wifi, 0, sizeof(g_wifi));
  nxmutex_init(&g_wifi.lock);
  g_wifi.seq_num = 0;

  /* Step 1: Initialize SDIO transport */

  ret = esp_hosted_sdio_init();
  if (ret < 0)
    {
      WIFI_ERR("SDIO init failed: %d\n", ret);
      return ret;
    }

  WIFI_INFO("SDIO initialized\n");

  /* Step 2: Wait for slave to be ready */

  /* The slave sends an INIT event when it's ready.
   * We'll set a default MAC for now and update it later.
   */

  g_wifi.mac[0] = 0x02;
  g_wifi.mac[1] = 0x00;
  g_wifi.mac[2] = 0x00;
  g_wifi.mac[3] = 0x00;
  g_wifi.mac[4] = 0x00;
  g_wifi.mac[5] = 0x01;

  /* Step 3: Register network device */

  g_wifi.netdev.d_ifup    = esp_wifi_ifup;
  g_wifi.netdev.d_ifdown  = esp_wifi_ifdown;
  g_wifi.netdev.d_txavail = esp_wifi_txavail;
#ifdef CONFIG_NETDEV_IOCTL
  g_wifi.netdev.d_ioctl   = esp_wifi_ioctl;
#endif
  g_wifi.netdev.d_private = &g_wifi;

  memcpy(g_wifi.netdev.d_mac.ether.ether_addr_octet, g_wifi.mac, 6);

  WIFI_INFO("Registering netdev...\n");
  ret = netdev_register(&g_wifi.netdev, NET_LL_IEEE80211);
  if (ret < 0)
    {
      WIFI_ERR("netdev_register failed: %d\n", ret);
      return ret;
    }

  WIFI_INFO("WiFi interface registered as wlan0\n");
  return OK;
}

/****************************************************************************
 * esp_hosted_transport.c
 *
 * Transport layer implementation for esp-hosted protocol.
 * Handles sending and receiving packets with proper framing.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <debug.h>
#include <errno.h>
#include <string.h>
#include <syslog.h>

#include "esp_hosted_nuttx.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG "hosted"
#define HOSTED_ERR(...)  syslog(LOG_ERR, TAG ": " __VA_ARGS__)
#define HOSTED_INFO(...) syslog(LOG_INFO, TAG ": " __VA_ARGS__)
#define HOSTED_DBG(...)  syslog(LOG_DEBUG, TAG ": " __VA_ARGS__)

/* Max write buffer retries */

#define MAX_WRITE_BUF_RETRIES  50
#define WRITE_BUF_RETRY_US     400

/* Max SDIO write retries */

#define MAX_SDIO_WRITE_RETRY   2

/****************************************************************************
 * Private Data
 ****************************************************************************/

static mutex_t g_transport_lock = NXMUTEX_INITIALIZER;
static uint16_t g_tx_seq_num = 0;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: compute_checksum
 *
 * Description:
 *   Compute checksum for payload header + data.
 *
 ****************************************************************************/

static uint16_t compute_checksum(const uint8_t *data, uint16_t len)
{
  uint16_t checksum = 0;
  int i;

  for (i = 0; i < (int)len; i++)
    {
      checksum += data[i];
    }

  return checksum;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp_hosted_sdio_send
 *
 * Description:
 *   Send a packet over SDIO to ESP32-C6.
 *   Constructs the esp-hosted payload header and sends via SDIO.
 *
 ****************************************************************************/

int esp_hosted_sdio_send(uint8_t if_type, uint8_t if_num,
                         const uint8_t *data, uint16_t len)
{
  struct esp_payload_header_s *hdr;
  uint8_t *sendbuf;
  uint16_t total_len;
  uint32_t buf_needed;
  uint32_t buf_available;
  int retries;
  int ret;

  if (data == NULL || len == 0 || len > MAX_PAYLOAD_SIZE)
    {
      HOSTED_ERR("Invalid send params: len=%u\n", len);
      return -EINVAL;
    }

  /* Allocate send buffer */

  total_len = ESP_PAYLOAD_HEADER_SIZE + len;
  sendbuf = (uint8_t *)kmm_malloc(total_len);
  if (sendbuf == NULL)
    {
      HOSTED_ERR("Failed to allocate send buffer\n");
      return -ENOMEM;
    }

  /* Build payload header */

  hdr = (struct esp_payload_header_s *)sendbuf;
  memset(hdr, 0, ESP_PAYLOAD_HEADER_SIZE);

  hdr->if_type = if_type & 0x0F;
  hdr->if_num  = if_num & 0x0F;
  hdr->len     = len;
  hdr->offset  = ESP_PAYLOAD_HEADER_SIZE;
  hdr->seq_num = g_tx_seq_num++;

  /* Copy payload */

  memcpy(sendbuf + ESP_PAYLOAD_HEADER_SIZE, data, len);

  /* Compute checksum */

  hdr->checksum = compute_checksum(sendbuf, total_len);

  /* Check if write buffer is available on slave */

  nxmutex_lock(&g_transport_lock);

  retries = MAX_WRITE_BUF_RETRIES;
  while (retries > 0)
    {
      ret = esp_hosted_sdio_get_tx_buf_num(&buf_available);
      if (ret < 0)
        {
          HOSTED_ERR("Failed to get tx buf num: %d\n", ret);
          nxmutex_unlock(&g_transport_lock);
          kmm_free(sendbuf);
          return ret;
        }

      buf_needed = (total_len + ESP_RX_BUFFER_SIZE - 1) / ESP_RX_BUFFER_SIZE;

      if (buf_available >= buf_needed)
        {
          break;
        }

      retries--;
      up_udelay(WRITE_BUF_RETRY_US);
    }

  if (retries == 0)
    {
      HOSTED_DBG("No write buffers available\n");
      nxmutex_unlock(&g_transport_lock);
      kmm_free(sendbuf);
      return -EBUSY;
    }

  /* Write data to SDIO */

  retries = MAX_SDIO_WRITE_RETRY;
  while (retries > 0)
    {
      ret = esp_hosted_sdio_write_block(ESP_SLAVE_CMD53_END_ADDR - total_len,
                                        sendbuf, total_len);
      if (ret >= 0)
        {
          break;
        }

      HOSTED_ERR("SDIO write failed: %d\n", ret);
      retries--;
    }

  /* Update TX buffer count */

  esp_hosted_sdio_update_tx_count(buf_needed);

  nxmutex_unlock(&g_transport_lock);
  kmm_free(sendbuf);

  if (ret < 0)
    {
      HOSTED_ERR("SDIO write failed after retries\n");
      return ret;
    }

  HOSTED_DBG("Sent %u bytes, if_type=%d\n", len, if_type);
  return OK;
}

/****************************************************************************
 * Name: esp_hosted_sdio_recv
 *
 * Description:
 *   Receive a packet from SDIO.
 *   Reads the packet, parses the header, and returns the payload.
 *
 ****************************************************************************/

int esp_hosted_sdio_recv(uint8_t *if_type, uint8_t *if_num,
                         uint8_t *data, uint16_t max_len)
{
  struct esp_payload_header_s *hdr;
  uint32_t interrupts;
  uint32_t len_from_slave;
  uint16_t len;
  uint16_t offset;
  int ret;

  /* Check for interrupts */

  ret = esp_hosted_sdio_get_intr(&interrupts);
  if (ret < 0)
    {
      return ret;
    }

  /* Check for new packet interrupt */

  if (!(interrupts & (1 << SDIO_INT_NEW_PACKET)))
    {
      return 0;  /* No data available */
    }

  /* Clear interrupt */

  esp_hosted_sdio_clear_intr(interrupts);

  /* Get packet length from slave */

  ret = esp_hosted_sdio_get_packet_len(&len_from_slave);
  if (ret < 0 || len_from_slave == 0)
    {
      return 0;
    }

  if (len_from_slave > ESP_RX_BUFFER_SIZE)
    {
      HOSTED_ERR("Packet too large: %lu\n", (unsigned long)len_from_slave);
      return -E2BIG;
    }

  /* Read data from SDIO */

  ret = esp_hosted_sdio_read_block(ESP_SLAVE_CMD53_END_ADDR - len_from_slave,
                                   data, len_from_slave);
  if (ret < 0)
    {
      HOSTED_ERR("SDIO read failed: %d\n", ret);
      return ret;
    }

  /* Update RX byte count */

  esp_hosted_sdio_update_rx_count(len_from_slave);

  /* Parse payload header */

  hdr = (struct esp_payload_header_s *)data;
  len = hdr->len;
  offset = hdr->offset;

  /* Validate header */

  if (len == 0 || offset != ESP_PAYLOAD_HEADER_SIZE ||
      len > MAX_PAYLOAD_SIZE)
    {
      HOSTED_DBG("Invalid header: len=%u offset=%u\n", len, offset);
      return 0;
    }

  /* Return interface info */

  if (if_type != NULL)
    {
      *if_type = hdr->if_type;
    }

  if (if_num != NULL)
    {
      *if_num = hdr->if_num;
    }

  /* Move payload to the beginning of the buffer */

  if (offset > 0 && len > 0)
    {
      memmove(data, data + offset, len);
    }

  HOSTED_DBG("Received %u bytes, if_type=%d\n", len, hdr->if_type);
  return len;
}

