    up_putc('0' + (ioe & 0xF));
    up_puts("\n");
  }

/* Enable function 1 */

ioe |= 0x02;  /* FUNC1_EN_MASK */
ret = sdio_cmd52_write(0, SD_IO_CCCR_FN_ENABLE, ioe, NULL);
if (ret < 0)
  {
    up_puts("SDIO: enable function 1 failed\n");
    return ret;
  }

/* Read back IOE to verify */

ret = sdio_cmd52_read(0, SD_IO_CCCR_FN_ENABLE, &ioe);
if (ret >= 0)
  {
    up_puts("SDIO: IOE after enable=0x");
    up_putc('0' + ((ioe >> 4) & 0xF));
    up_putc('0' + (ioe & 0xF));
    up_puts("\n");
  }

up_puts("SDIO: function 1 enabled\n");

/* Wait for function 1 to be ready */

up_puts("SDIO: waiting for function 1...\n");
timeout = SDIO_INIT_TIMEOUT_MS;  /* Use longer timeout */
int retry_count = 0;
while (timeout-- > 0)
  {
    uint8_t ready = 0;
    ret = sdio_cmd52_read(0, SD_IO_CCCR_FN_READY, &ready);
    if (ret >= 0 && (ready & 0x02))
      {
        up_puts("SDIO: function 1 ready\n");
        break;
      }

    /* Print IOR value every 100 retries */

    if ((retry_count % 100) == 0)
      {
        up_puts("SDIO: IOR=0x");
        up_putc('0' + ((ready >> 4) & 0xF));
        up_putc('0' + (ready & 0xF));
        up_puts("\n");
      }

    retry_count++;
    up_mdelay(10);  /* Wait 10ms between retries */
  }

if (timeout <= 0)
  {
    up_puts("SDIO: function 1 not ready (timeout)\n");
    up_puts("SDIO: Is ESP32-C6 flashed with esp-hosted slave firmware?\n");
    return -ETIMEDOUT;
  }

