/****************************************************************************
 * esp_hosted_sdio.c
 *
 * SDIO transport layer for esp-hosted protocol.
 * Uses ESP-IDF SDMMC HAL for proper SDIO communication.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <debug.h>
#include <errno.h>
#include <string.h>
#include <stdio.h>

#include "esp_hosted_nuttx.h"

/* ESP-IDF SDMMC HAL includes */

#include "driver/sdmmc_host.h"
#include "driver/sdmmc_defs.h"
#include "sdmmc_cmd.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SDIO_TAG "sdio"
#define SDIO_ERR(...)   syslog(LOG_ERR, SDIO_TAG ": " __VA_ARGS__)
#define SDIO_INFO(...)  syslog(LOG_INFO, SDIO_TAG ": " __VA_ARGS__)
#define SDIO_DBG(...)   syslog(LOG_DEBUG, SDIO_TAG ": " __VA_ARGS__)

#define FUNC1_EN_MASK   (BIT(1))
#define SDIO_INIT_MAX_RETRY 10

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct esp_sdio_dev_s
{
  sdmmc_card_t  card;          /* SDMMC card handle */
  mutex_t       lock;          /* Mutex for thread safety */
  bool          initialized;   /* Initialization state */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct esp_sdio_dev_s g_sdio;

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp_hosted_sdio_init
 *
 * Description:
 *   Initialize SDIO using ESP-IDF SDMMC HAL.
 *
 ****************************************************************************/

int esp_hosted_sdio_init(void)
{
  esp_err_t ret;

  up_puts("SDIO: init entry\n");

  memset(&g_sdio, 0, sizeof(g_sdio));
  nxmutex_init(&g_sdio.lock);

  /* Step 1: Initialize SDMMC host */

  up_puts("SDIO: initializing host...\n");
  ret = sdmmc_host_init();
  if (ret != ESP_OK)
    {
      up_puts("SDIO: host init failed\n");
      return -EIO;
    }

  up_puts("SDIO: host init done\n");

  /* Step 2: Configure and initialize slot 1 */

  sdmmc_slot_config_t slot_config = SDMMC_SLOT_CONFIG_DEFAULT();

  /* Configure GPIO pins for SDIO
   * Using SLOT1 with GPIO matrix:
   *   CLK = GPIO18
   *   CMD = GPIO19
   *   D0  = GPIO14
   *   D1  = GPIO15
   *   D2  = GPIO16
   *   D3  = GPIO17
   */

  slot_config.clk = 18;
  slot_config.cmd = 19;
  slot_config.d0  = 14;
  slot_config.d1  = 15;
  slot_config.d2  = 16;
  slot_config.d3  = 17;
  slot_config.width = 4;

  up_puts("SDIO: initializing slot 1...\n");
  ret = sdmmc_host_init_slot(1, &slot_config);
  if (ret != ESP_OK)
    {
      up_puts("SDIO: slot init failed\n");
      return -EIO;
    }

  up_puts("SDIO: slot init done\n");

  /* Step 3: Initialize the SDIO card */

  sdmmc_card_t *card = &g_sdio.card;
  memset(card, 0, sizeof(sdmmc_card_t));
  card->host.slot = 1;
  card->host.io_voltage = 3.3f;
  card->host.max_freq_khz = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_FREQ / 1000;

  /* Set host capabilities */

  card->host.flags = SDMMC_HOST_FLAG_4BIT;

  up_puts("SDIO: initializing card...\n");

  /* Initialize SDIO card with retries */

  int retry;
  for (retry = 0; retry < SDIO_INIT_MAX_RETRY; retry++)
    {
      ret = sdmmc_io_init(card);
      if (ret == ESP_OK)
        {
          break;
        }

      up_puts("SDIO: card init retry\n");
      up_mdelay(100);
    }

  if (ret != ESP_OK)
    {
      up_puts("SDIO: card init failed\n");
      return -EIO;
    }

  up_puts("SDIO: card init done\n");

  /* Step 4: Enable SDIO function 1 */

  uint8_t ioe = 0;
  uint8_t ior = 0;

  /* Read current IO Enable */

  ret = sdmmc_io_read_byte(card, 0, SD_IO_CCCR_FN_ENABLE, &ioe);
  if (ret != ESP_OK)
    {
      up_puts("SDIO: read IOE failed\n");
      return -EIO;
    }

  up_puts("SDIO: IOE=0x\n");

  /* Enable function 1 */

  ioe |= FUNC1_EN_MASK;
  ret = sdmmc_io_write_byte(card, 0, SD_IO_CCCR_FN_ENABLE, ioe, NULL);
  if (ret != ESP_OK)
    {
      up_puts("SDIO: write IOE failed\n");
      return -EIO;
    }

  up_puts("SDIO: function 1 enabled\n");

  /* Wait for function 1 to be ready */

  up_puts("SDIO: waiting for function 1...\n");
  int i;
  for (i = 0; i < SDIO_INIT_MAX_RETRY; i++)
    {
      ret = sdmmc_io_read_byte(card, 0, SD_IO_CCCR_FN_READY, &ior);
      if (ret != ESP_OK)
        {
          up_puts("SDIO: read IOR failed\n");
          return -EIO;
        }

      if (ior & FUNC1_EN_MASK)
        {
          up_puts("SDIO: function 1 ready\n");
          break;
        }

      up_mdelay(10);
    }

  if (i >= SDIO_INIT_MAX_RETRY)
    {
      up_puts("SDIO: function 1 not ready\n");
      return -ETIMEDOUT;
    }

  /* Step 5: Enable interrupts for function 1 */

  uint8_t ie = 0;
  ret = sdmmc_io_read_byte(card, 0, SD_IO_CCCR_INT_ENABLE, &ie);
  if (ret == ESP_OK)
    {
      ie |= BIT(0) | FUNC1_EN_MASK;
      sdmmc_io_write_byte(card, 0, SD_IO_CCCR_INT_ENABLE, ie, NULL);
    }

  /* Step 6: Set block size to 512 for function 1 */

  uint16_t block_size = 512;
  ret = sdmmc_io_write_byte(card, 0, SD_IO_CCCR_BLKSIZEL,
                            block_size & 0xFF, NULL);
  ret |= sdmmc_io_write_byte(card, 0, SD_IO_CCCR_BLKSIZEH,
                             (block_size >> 8) & 0xFF, NULL);

  if (ret != ESP_OK)
    {
      up_puts("SDIO: set block size failed\n");
    }

  up_puts("SDIO: init complete\n");

  g_sdio.initialized = true;
  return OK;
}

/****************************************************************************
 * Name: esp_hosted_sdio_read_reg
 *
 * Description:
 *   Read a register from SDIO slave.
 *
 ****************************************************************************/

int esp_hosted_sdio_read_reg(uint32_t addr, uint8_t *data, uint16_t size)
{
  esp_err_t ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  if (size == 1)
    {
      ret = sdmmc_io_read_byte(&g_sdio.card, 1, addr, data);
    }
  else if (size == 4)
    {
      ret = sdmmc_io_read_bytes(&g_sdio.card, 1, addr, 4, data);
    }
  else
    {
      return -EINVAL;
    }

  return (ret == ESP_OK) ? OK : -EIO;
}

/****************************************************************************
 * Name: esp_hosted_sdio_write_reg
 *
 * Description:
 *   Write a register to SDIO slave.
 *
 ****************************************************************************/

int esp_hosted_sdio_write_reg(uint32_t addr, uint8_t *data, uint16_t size)
{
  esp_err_t ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  if (size == 1)
    {
      ret = sdmmc_io_write_byte(&g_sdio.card, 1, addr, *data, NULL);
    }
  else if (size == 4)
    {
      ret = sdmmc_io_write_bytes(&g_sdio.card, 1, addr, 4, data);
    }
  else
    {
      return -EINVAL;
    }

  return (ret == ESP_OK) ? OK : -EIO;
}

/****************************************************************************
 * Name: esp_hosted_sdio_read_block
 *
 * Description:
 *   Read a block of data from SDIO slave.
 *
 ****************************************************************************/

int esp_hosted_sdio_read_block(uint32_t addr, uint8_t *data, uint16_t size)
{
  esp_err_t ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  nxmutex_lock(&g_sdio.lock);
  ret = sdmmc_io_read_bytes(&g_sdio.card, 1, addr, size, data);
  nxmutex_unlock(&g_sdio.lock);

  return (ret == ESP_OK) ? size : -EIO;
}

/****************************************************************************
 * Name: esp_hosted_sdio_write_block
 *
 * Description:
 *   Write a block of data to SDIO slave.
 *
 ****************************************************************************/

int esp_hosted_sdio_write_block(uint32_t addr, const uint8_t *data,
                                uint16_t size)
{
  esp_err_t ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  nxmutex_lock(&g_sdio.lock);
  ret = sdmmc_io_write_bytes(&g_sdio.card, 1, addr, size, data);
  nxmutex_unlock(&g_sdio.lock);

  return (ret == ESP_OK) ? size : -EIO;
}

/****************************************************************************
 * Name: esp_hosted_sdio_get_intr
 *
 * Description:
 *   Get SDIO interrupt status.
 *
 ****************************************************************************/

int esp_hosted_sdio_get_intr(uint32_t *interrupts)
{
  esp_err_t ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  ret = sdmmc_io_read_bytes(&g_sdio.card, 1, ESP_SLAVE_INT_RAW_REG,
                            4, (uint8_t *)interrupts);

  return (ret == ESP_OK) ? OK : -EIO;
}

/****************************************************************************
 * Name: esp_hosted_sdio_clear_intr
 *
 * Description:
 *   Clear SDIO interrupts.
 *
 ****************************************************************************/

int esp_hosted_sdio_clear_intr(uint32_t interrupts)
{
  esp_err_t ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  ret = sdmmc_io_write_bytes(&g_sdio.card, 1, ESP_SLAVE_INT_CLR_REG,
                             4, (uint8_t *)&interrupts);

  return (ret == ESP_OK) ? OK : -EIO;
}

/****************************************************************************
 * Name: esp_hosted_sdio_get_packet_len
 *
 * Description:
 *   Get the length of the next packet from slave.
 *
 ****************************************************************************/

int esp_hosted_sdio_get_packet_len(uint32_t *len)
{
  esp_err_t ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  ret = sdmmc_io_read_bytes(&g_sdio.card, 1, ESP_SLAVE_PACKET_LEN_REG,
                            4, (uint8_t *)len);

  if (ret != ESP_OK)
    {
      return -EIO;
    }

  *len &= ESP_SLAVE_LEN_MASK;
  return OK;
}

/****************************************************************************
 * Name: esp_hosted_sdio_get_tx_buf_num
 *
 * Description:
 *   Get the number of available TX buffers on slave.
 *
 ****************************************************************************/

int esp_hosted_sdio_get_tx_buf_num(uint32_t *tx_num)
{
  esp_err_t ret;
  uint32_t len = 0;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  ret = sdmmc_io_read_bytes(&g_sdio.card, 1, ESP_SLAVE_TOKEN_RDATA,
                            4, (uint8_t *)&len);

  if (ret != ESP_OK)
    {
      return -EIO;
    }

  len = (len >> 16) & ESP_TX_BUFFER_MASK;
  *tx_num = len;
  return OK;
}

/****************************************************************************
 * Name: esp_hosted_sdio_generate_slave_intr
 *
 * Description:
 *   Generate an interrupt to the slave.
 *
 ****************************************************************************/

int esp_hosted_sdio_generate_slave_intr(uint8_t intr_no)
{
  esp_err_t ret;
  uint8_t intr_mask = (1 << intr_no);

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  ret = sdmmc_io_write_byte(&g_sdio.card, 1, HOST_TO_SLAVE_INTR,
                            intr_mask, NULL);

  return (ret == ESP_OK) ? OK : -EIO;
}

/****************************************************************************
 * Name: esp_hosted_sdio_update_rx_count
 *
 * Description:
 *   Update the RX byte counter (no-op for HAL-based implementation).
 *
 ****************************************************************************/

void esp_hosted_sdio_update_rx_count(uint32_t len)
{
  /* No-op: HAL handles this internally */
}

/****************************************************************************
 * Name: esp_hosted_sdio_update_tx_count
 *
 * Description:
 *   Update the TX buffer counter (no-op for HAL-based implementation).
 *
 ****************************************************************************/

void esp_hosted_sdio_update_tx_count(uint32_t buf_count)
{
  /* No-op: HAL handles this internally */
}

/****************************************************************************
 * esp_hosted_sdio.c
 *
 * SDIO transport layer for esp-hosted protocol.
 * ESP32-P4 (host) <-> SDIO <-> ESP32-C6 (WiFi co-processor)
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <debug.h>
#include <errno.h>
#include <string.h>
#include <stdio.h>

#include "esp_hosted_nuttx.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SDIO_TAG "sdio"
#define SDIO_ERR(...)   syslog(LOG_ERR, SDIO_TAG ": " __VA_ARGS__)
#define SDIO_INFO(...)  syslog(LOG_INFO, SDIO_TAG ": " __VA_ARGS__)
#define SDIO_DBG(...)   syslog(LOG_DEBUG, SDIO_TAG ": " __VA_ARGS__)

/* SDIO command definitions */

#define SDIO_CMD_GO_IDLE_STATE      0
#define SDIO_CMD_SEND_OP_COND       5
#define SDIO_CMD_SEND_RELATIVE_ADDR 3
#define SDIO_CMD_SELECT_CARD        7
#define SDIO_CMD_IO_RW_DIRECT      52
#define SDIO_CMD_IO_RW_EXTENDED    53

/* SDIO CCCR registers */

#define SD_IO_CCCR_FN_ENABLE      0x02
#define SD_IO_CCCR_FN_READY       0x03
#define SD_IO_CCCR_INT_ENABLE     0x04
#define SD_IO_CCCR_BUS_WIDTH      0x07
#define SD_IO_CCCR_BLKSIZEL       0x10
#define SD_IO_CCCR_BLKSIZEH       0x11

/* ESP32-P4 SDMMC register base address */

#define SDMMC_BASE          0x50083000
#define SDMMC_CTRL          (SDMMC_BASE + 0x00)
#define SDMMC_CLKDIV        (SDMMC_BASE + 0x08)
#define SDMMC_CLKSRC        (SDMMC_BASE + 0x0C)
#define SDMMC_CLKENA        (SDMMC_BASE + 0x10)
#define SDMMC_TMOUT         (SDMMC_BASE + 0x14)
#define SDMMC_CTYPE         (SDMMC_BASE + 0x18)
#define SDMMC_BLKSIZ        (SDMMC_BASE + 0x1C)
#define SDMMC_BYTCNT        (SDMMC_BASE + 0x20)
#define SDMMC_INTMASK       (SDMMC_BASE + 0x24)
#define SDMMC_CMDARG        (SDMMC_BASE + 0x28)
#define SDMMC_CMD           (SDMMC_BASE + 0x2C)
#define SDMMC_RESP0         (SDMMC_BASE + 0x30)
#define SDMMC_RESP1         (SDMMC_BASE + 0x34)
#define SDMMC_RESP2         (SDMMC_BASE + 0x38)
#define SDMMC_RESP3         (SDMMC_BASE + 0x3C)
#define SDMMC_MINTSTS       (SDMMC_BASE + 0x40)
#define SDMMC_RINTSTS       (SDMMC_BASE + 0x44)
#define SDMMC_STATUS        (SDMMC_BASE + 0x48)
#define SDMMC_FIFOTH        (SDMMC_BASE + 0x4C)
#define SDMMC_CDETECT       (SDMMC_BASE + 0x50)
#define SDMMC_FIFO          (SDMMC_BASE + 0x200)
#define SDMMC_CLK_EDGE_SEL  (SDMMC_BASE + 0x7FC)

/* GPIO base for ESP32-P4 */

#define GPIO_BASE           0x500E0000
#define GPIO_FUNC_OUT_SEL   (GPIO_BASE + 0x554)
#define GPIO_ENABLE_W1TS    (GPIO_BASE + 0x20)

/* SDMMC SLOT1 signal indices */

#define SDMMC_SLOT1_D0      58
#define SDMMC_SLOT1_D1      59
#define SDMMC_SLOT1_D2      60
#define SDMMC_SLOT1_D3      61
#define SDMMC_SLOT1_CLK     56
#define SDMMC_SLOT1_CMD     57

/* Timing */

#define SDIO_INIT_TIMEOUT_MS   1000
#define SDIO_CMD_TIMEOUT_MS    100

/* Block size */

#define ESP_BLOCK_SIZE      512

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct esp_sdio_dev_s
{
  mutex_t    lock;
  uint16_t   rca;
  bool       initialized;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct esp_sdio_dev_s g_sdio;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void sdio_print_hex(uint32_t val, int digits)
{
  int i;
  for (i = (digits - 1) * 4; i >= 0; i -= 4)
    {
      uint8_t nibble = (val >> i) & 0xF;
      up_putc(nibble < 10 ? '0' + nibble : 'A' + nibble - 10);
    }
}

static int sdio_send_cmd(uint32_t cmd, uint32_t arg,
                         uint32_t *resp, bool need_response)
{
  volatile uint32_t *cmd_reg  = (volatile uint32_t *)SDMMC_CMD;
  volatile uint32_t *arg_reg  = (volatile uint32_t *)SDMMC_CMDARG;
  volatile uint32_t *rint_reg = (volatile uint32_t *)SDMMC_RINTSTS;
  volatile uint32_t *status   = (volatile uint32_t *)SDMMC_STATUS;
  int timeout;

  /* Wait for controller not busy */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while ((*status & (1 << 9)) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  /* Clear pending interrupts */

  *rint_reg = 0xFFFFFFFF;

  /* Set argument */

  *arg_reg = arg;

  /* Build command register value
   * Bits: [5:0]=cmd_index, [6]=response_expect, [8]=check_response_crc,
   *       [16]=card_num, [31]=start_command
   */

  uint32_t cmd_val = (cmd & 0x3F) | (1 << 16) | (1 << 31);

  if (need_response)
    {
      cmd_val |= (1 << 6);  /* response_expect */
      cmd_val |= (1 << 8);  /* check_response_crc */
    }

  /* For CMD0, send initialization sequence */

  if (cmd == 0)
    {
      cmd_val |= (1 << 15);
    }

  /* Write command to register */

  *cmd_reg = cmd_val;

  /* Wait for command done */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while ((*cmd_reg & (1 << 31)) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      up_puts("SDIO: CMD timeout\n");
      return -ETIMEDOUT;
    }

  /* Check raw interrupt status */

  uint32_t rint = *rint_reg;

  /* Check for response timeout (bit 8) */

  if (rint & (1 << 8))
    {
      *rint_reg = (1 << 8);
      up_puts("SDIO: response timeout\n");
      return -ETIMEDOUT;
    }

  /* Check for response error (bit 1) */

  if (rint & (1 << 1))
    {
      *rint_reg = (1 << 1);
      up_puts("SDIO: response error\n");
      return -EIO;
    }

  /* Check for response CRC error (bit 6) */

  if (rint & (1 << 6))
    {
      *rint_reg = (1 << 6);
      up_puts("SDIO: CRC error\n");
      return -EIO;
    }

  /* Clear command done interrupt */

  if (rint & (1 << 2))
    {
      *rint_reg = (1 << 2);
    }

  /* Read response if requested */

  if (resp != NULL && need_response)
    {
      *resp = *((volatile uint32_t *)SDMMC_RESP0);
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int esp_hosted_sdio_init(void)
{
  volatile uint32_t *clk_rst_reg;
  int timeout;
  uint32_t resp;
  int ret;

  up_puts("SDIO: init entry\n");

  memset(&g_sdio, 0, sizeof(g_sdio));
  nxmutex_init(&g_sdio.lock);

  /* Step 1: Enable SDMMC peripheral clock */

  up_puts("SDIO: enabling clock...\n");
  clk_rst_reg = (volatile uint32_t *)0x500E6004;
  *clk_rst_reg |= (1 << 12);

  /* Step 2: Configure GPIO pins for SDIO */

  up_puts("SDIO: configuring GPIO...\n");
  volatile uint32_t *func_out;
  volatile uint32_t *enable;

  /* GPIO14 -> SDMMC SLOT1 D0 */
  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 14 * 4);
  *func_out = SDMMC_SLOT1_D0;
  enable = (volatile uint32_t *)(GPIO_ENABLE_W1TS);
  *enable = (1 << 14);

  /* GPIO15 -> SDMMC SLOT1 D1 */
  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 15 * 4);
  *func_out = SDMMC_SLOT1_D1;
  *enable = (1 << 15);

  /* GPIO16 -> SDMMC SLOT1 D2 */
  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 16 * 4);
  *func_out = SDMMC_SLOT1_D2;
  *enable = (1 << 16);

  /* GPIO17 -> SDMMC SLOT1 D3 */
  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 17 * 4);
  *func_out = SDMMC_SLOT1_D3;
  *enable = (1 << 17);

  /* GPIO18 -> SDMMC SLOT1 CLK */
  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 18 * 4);
  *func_out = SDMMC_SLOT1_CLK;
  *enable = (1 << 18);

  /* GPIO19 -> SDMMC SLOT1 CMD */
  func_out = (volatile uint32_t *)(GPIO_FUNC_OUT_SEL + 19 * 4);
  *func_out = SDMMC_SLOT1_CMD;
  *enable = (1 << 19);

  up_puts("SDIO: GPIO done\n");

  /* Step 3: Reset the SDMMC controller */

  volatile uint32_t *ctrl = (volatile uint32_t *)SDMMC_CTRL;
  *ctrl = 0x7;
  up_mdelay(10);

  timeout = 100;
  while ((*ctrl & 0x7) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  up_puts("SDIO: controller reset done\n");

  /* Step 4: Enable interrupts */

  volatile uint32_t *intmask = (volatile uint32_t *)SDMMC_INTMASK;
  *intmask = 0xFFFF;
  *ctrl |= (1 << 4);  /* int_enable */

  /* Step 5: Configure clock (400kHz for identification) */

  volatile uint32_t *clkdiv = (volatile uint32_t *)SDMMC_CLKDIV;
  *clkdiv = (200 << 8) | 200;

  volatile uint32_t *clksrc = (volatile uint32_t *)SDMMC_CLKSRC;
  *clksrc = 0x01;  /* Use divider 1 for card 1 */

  volatile uint32_t *clkena = (volatile uint32_t *)SDMMC_CLKENA;
  *clkena = 0x2;  /* Enable clock for card 1 */

  volatile uint32_t *tmout = (volatile uint32_t *)SDMMC_TMOUT;
  *tmout = (0xFFFFFF << 8) | 0x64;

  volatile uint32_t *ctype = (volatile uint32_t *)SDMMC_CTYPE;
  *ctype = 0;  /* 1-bit mode initially */

  up_puts("SDIO: clock configured\n");

  /* Step 6: Send CMD0 (GO_IDLE_STATE) */

  up_puts("SDIO: sending CMD0...\n");
  ret = sdio_send_cmd(SDIO_CMD_GO_IDLE_STATE, 0, NULL, false);
  if (ret < 0)
    {
      up_puts("SDIO: CMD0 failed\n");
      return ret;
    }

  up_puts("SDIO: CMD0 done\n");
  up_mdelay(10);

  /* Step 7: Send CMD5 (IO_SEND_OP_COND) */

  up_puts("SDIO: sending CMD5...\n");
  ret = sdio_send_cmd(SDIO_CMD_SEND_OP_COND, 0, &resp, true);
  if (ret < 0)
    {
      up_puts("SDIO: CMD5 failed\n");
      return ret;
    }

  up_puts("SDIO: CMD5 resp=0x");
  sdio_print_hex(resp, 8);
  up_puts("\n");

  /* Send CMD5 with voltage window */
  ret = sdio_send_cmd(SDIO_CMD_SEND_OP_COND, 0x00FF8000, &resp, true);
  up_mdelay(10);

  /* Step 8: Send CMD3 (SEND_RELATIVE_ADDR) */

  up_puts("SDIO: sending CMD3...\n");
  ret = sdio_send_cmd(SDIO_CMD_SEND_RELATIVE_ADDR, 0, &resp, true);
  if (ret < 0)
    {
      up_puts("SDIO: CMD3 failed\n");
      return ret;
    }

  up_puts("SDIO: CMD3 resp=0x");
  sdio_print_hex(resp, 8);
  up_puts("\n");

  g_sdio.rca = (resp >> 16) & 0xFFFF;

  /* Step 9: Send CMD7 (SELECT_CARD) */

  up_puts("SDIO: sending CMD7...\n");
  ret = sdio_send_cmd(SDIO_CMD_SELECT_CARD,
                      ((uint32_t)g_sdio.rca) << 16, &resp, true);
  if (ret < 0)
    {
      up_puts("SDIO: CMD7 failed\n");
      return ret;
    }

  up_puts("SDIO: CMD7 resp=0x");
  sdio_print_hex(resp, 8);
  up_puts("\n");

  up_puts("SDIO: init complete\n");
  g_sdio.initialized = true;
  return OK;
}

